INSERT INTO public.hexagrams (id, binary_code, symbol, name_ko, name_hanja, name_full, judgment_text, judgment_ko, tanjon_text, xiang_text, wenyan_text) VALUES (1, '111111', '䷀', '건', '乾', '중천건', '乾 元亨，利貞。', '건(乾)은 으뜸이고 형통하니, 곧게 지키면 이롭다.', '彖曰：大哉「乾元」，萬物資始，乃統天。雲行雨施，品物流形。大明終始，六位時成。時乘六龍以御天。乾道變化，各正性命。保合大和，乃「利貞」。首出庶物，萬國咸寧。', '象曰：天行健，君子以自强不息。', '文言曰：「元」者、善之長也，「亨」者、嘉之會也，《利》者、義之和也，「貞」者、事之幹也。君子體仁足以長人，嘉會足以合禮，利物足以和義，貞固足以幹事。君子行此四德者，故曰「乾、元、亨、利、貞」。初九曰、「潛龍勿用」，何謂也？子曰：「龍、德而隱者也。不易乎世，不成乎名，遯世無悶，不見是而無悶。樂則行之，憂則違之，確乎其不可拔，潛龍也。」九二曰、「見龍在田、利見大人」，何謂也？子曰：「龍德而正中者也。庸言之信，庸行之謹，閑邪存其誠，善世而不伐，德博而化。《易》曰、『見龍在田、利見大人』，君德也。」九三曰、「君子終日乾乾、夕惕若、厲、無咎」。何謂也？子曰：「君子進德修業，忠信，所以進德也，修辭立其誠，所以居業也。知至至之，可與幾也，知終終之，可與存義也。是故居上位而不驕，在下位而不憂，故乾乾因其時而惕，雖危無咎矣。」九四曰、「或躍在淵、無咎。」何謂也？子曰：「上下無常，非爲邪也。進退無恒，非離群也。君子進德修業、欲及時也，故無咎。」九五曰、「飛龍在天、利見大人」。何謂也？子曰：「同聲相應，同氣相求。水流濕，火就燥，雲從龍，風從虎，聖人作而萬物覩。本乎天者親上，本乎地者親下，則各從其類也。」上九曰、「亢龍有悔」，何謂也？子曰：「貴而無位，高而無民，賢人在下位而無輔，是以動而有悔也。」「潛龍勿用」、下也，「見龍在田」、時舍也，「終日乾乾」、行事也，「或躍在淵」、自試也，「飛龍在天」、上治也，「亢龍有悔」、窮之災也。乾元「用九」、天下治也。「潛龍勿用」，陽氣潛藏。「見龍在田」，天下文明。「終日乾乾」，與時偕行。「或躍在淵」，乾道乃革。「飛龍在天」，乃位乎天德。「亢龍有悔」，與時偕極。乾元「用九」，乃見天則。《乾》「元」「亨」者、始而亨者也。「利貞」者、性情也。乾始能以美利利天下，不言所利，大矣哉！大哉乾乎！剛健中正，純粹精也。六爻發揮，旁通情也。「時乘六龍」、以「御天」也，「雲行雨施」、天下平也。君子以成德爲行，日可見之行也。「潛」之爲言也，隱而未見，行而未成，是以君子「弗用」也。君子學以聚之，問以辨之，寬以居之，仁以行之。《易》曰、「見龍在田、利見大人」，君德也。九三重剛而不中，上不在天，下不在田，故「乾乾」因其時而「惕」，雖危「無咎」矣。九四重剛而不中，上不在天，下不在田，中不在人，故「或」之。「或」之者、疑之也，故「無咎」。夫「大人」者、與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶，先天而天弗違，後天而奉天時。天且弗違，而況於人乎？況於鬼神乎？「亢」之爲言也，知進而不知退，知存而不知亡，知得而不知喪。其唯聖人乎！知進退存亡而不失其正者，其唯聖人乎！'),(2, '000000', '䷁', '곤', '坤', '중지곤', '坤 元亨。利牝馬之貞。君子有攸往，先迷後得主，利，西南得朋，東北喪朋。安貞吉。', '곤은 크게 형통하다. 암말의 곧음이 이롭다. 군자가 나아갈 바가 있으되, 먼저 가면 미혹되고 뒤따르면 주인을 얻으니 이롭다. 서남쪽에서는 벗을 얻고, 동북쪽에서는 벗을 잃는다. 편안히 곧게 지키면 길하다.', '彖曰：至哉「坤元」，萬物資生，乃順承天。坤厚載物，德合無疆。含弘光大，品物咸「亨」。「牝馬」地類，行地無疆，柔順「利貞」。「君子」攸行，「先迷」失道，「後」順「得」常。「西南得朋」，乃與類行。「東北喪朋」，乃終有慶。「安貞」之「吉」，應地無疆。', '象曰：地勢坤。君子以厚德載物。', '文言曰：《坤》至柔而動也剛，至靜而德方，後得主而有常，含萬物而化光。坤道其順乎，承天而時行。積善之家必有餘慶，積不善之家必有餘殃。臣弒其君，子弒其父，非一朝一夕之故，其所由來者漸矣，由辨之不早辨也。《易》曰、「履霜、堅氷至」，蓋言順也。「直」其正也，「方」其義也。君子敬以直內，義以方外，敬義立而德不孤。「直、方、大、不習無不利」，則不疑其所行也。陰雖有美「含」之以從王事，弗敢成也。地道也，妻道也，臣道也。地道「無成」而代「有終」也。天地變化，草木蕃。天地閉，賢人隱。《易》曰、「括囊、無咎無譽」，蓋言謹也。君子「黃」中通理，正位居體，美在其中而暢於四支，發於事業，美之至也。陰疑於陽必「戰」，爲其嫌於無陽也，故稱「龍」焉。猶未離其類也，故稱「血」焉。夫「玄黃」者、天地之雜也。天玄而地黃。'),(3, '100010', '䷂', '준', '屯', '수뢰준', '屯 元亨，利貞。勿用有攸往。利建侯。', '준은 크게 형통하니, 곧게 지키면 이롭다. 나아갈 바를 두지 말라. 제후를 세우면 이롭다.', '彖曰：《屯》，剛柔始交而難生。動乎險中，大「亨貞」。雷雨之動滿盈，天造草昧。宜「建侯」而不寧。', '象曰：雲雷、屯。君子以經綸。', NULL),(4, '010001', '䷃', '몽', '蒙', '산수몽', '蒙 亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告。利貞。', '몽(蒙)은 형통하다. 내가 동몽을 구하는 것이 아니라 동몽이 나를 구한다. 처음 점치면 알려주지만, 두세 번 거듭하면 모독함이니, 모독하면 알려주지 않는다. 곧게 지키면 이롭다.', '彖曰：《蒙》，山下有險，險而止，《蒙》。《蒙》「亨」，以亨行，時中也。「匪我求童蒙、童蒙求我」，志應也。「初筮告」、以剛中也。「再三瀆、瀆則不告」，瀆蒙也。蒙以養正，聖功也。', '象曰：山下出泉，《蒙》。君子以果行育德。', NULL),(5, '111010', '䷄', '수', '需', '수천수', '需 有孚，光亨。貞吉。利涉大川。', '수는 미더움이 있으니, 크게 형통하다. 곧게 지키면 길하다. 큰 내를 건너는 것이 이롭다.', '彖曰：《需》、須也。險在前也，剛健而不陷，其義不困窮矣。《需》、「有孚、光亨、貞吉」，位乎天位以正中也。「利涉大川」、往有功也。', '象曰：雲上於天，《需》。君子以飮食宴樂。', NULL),(6, '010111', '䷅', '송', '訟', '천수송', '訟 有孚窒，惕，中吉，終凶。利見大人。不利涉大川。', '송(訟)은 미더움이 있으나 막혀 있고, 두려워하면 중(中)하여 길(吉)하나, 끝까지 가면 흉(凶)하다. 대인(大人)을 만나면 이롭고, 큰 내를 건너는 것은 이롭지 않다.', '彖曰：《訟》，上剛下險，險而健，訟。《訟》、「有孚、窒、惕、中吉」，剛來而得中也。「終凶」、訟不可成也。「利見大人」、尙中正也。「不利涉大川」、入于淵也。', '象曰：天與水違行，《訟》。君子以作事謀始。', NULL),(7, '010000', '䷆', '사', '師', '지수사', '師 貞丈人吉，無咎。', '사(師)는 곧게 지키고 장인(丈人)이면 길하며, 허물이 없다.', '彖曰：「師」、眾也，「貞」、正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下而民從之，「吉」、又何咎矣。', '象曰：地中有水，《師》。君子以容民畜眾。', NULL),(8, '000010', '䷇', '비', '比', '수지비', '比 吉。原筮元，永貞無咎。不寧方來，後夫凶。', '비(比)는 길하다. 으뜸을 점쳐 살피고, 길이 곧게 지키면 허물이 없다. 편안하지 못한 이들이 사방에서 오고, 뒤늦은 자는 흉하다.', '彖曰：（《比》、「吉」也），《比》、輔也，下順從也，「《比》、「吉」、原筮元、永貞無咎」，以剛中也。「不寧方來」、上下應也，「後夫凶」、其道窮也。', '象曰：地上有水，《比》。先王以建萬國，親諸侯。', NULL),(9, '111011', '䷈', '소축', '小畜', '풍천소축', '小畜 亨。密雲不雨，自我西郊。', '소축(小畜)은 형통하다. 빽빽한 구름이 비를 내리지 않으니, 우리 서쪽 교외로부터이다.', '彖曰：《小畜》，柔得位而上下應之，曰《小畜》。健而巽，剛中而志行，乃「亨」。「密雲不雨」、尙往也，「自我西郊」、施未行也。', '象曰：風行天上，《小畜》。君子以懿文德。', NULL),(10, '110111', '䷉', '리', '履', '천택리', '履虎尾，不咥人。亨。', '호랑이 꼬리를 밟으나 사람을 물지 않는다. 형통하다.', '彖曰：《履》、柔履剛也。說而應乎乾，是以「履虎尾、不咥人、亨」，剛中正、履帝位而不疚，光明也。', '象曰：上天下澤，《履》。君子以辨上下，定民志。', NULL),(11, '111000', '䷊', '태', '泰', '지천태', '泰 小往大來，吉，亨。', '태(泰)는 작은 것은 가고 큰 것은 오니, 길하고 형통하다.', '彖曰：「《泰》、小往大來、吉、亨」。則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人，君子道長，小人道消也。', '象曰：天地交，《泰》。后以財成天地之道，輔相天地之宜，以左右民。', NULL),(12, '000111', '䷋', '비', '否', '천지비', '否之匪人。不利君子貞。大往小來。', '비(否)는 사람이 아니다. 군자가 곧게 지킴에 이롭지 않다. 큰 것이 가고 작은 것이 온다.', '彖曰：「否之匪人、不利君子貞、大往小來」。則是天地不交而萬物不通也，上下不交而天下無邦也；內陰而外陽，內柔而外剛，內小人而外君子，小人道長，君子道消也。', '象曰：天地不交，《否》。君子以儉德辟難，不可榮以祿。', NULL),(13, '101111', '䷌', '동인', '同人', '천화동인', '同人于野，亨。利涉大川。利君子貞。', '들에서 사람들과 함께하니 형통하다. 큰 내를 건너는 것이 이롭다. 군자가 곧게 지키면 이롭다.', '彖曰：《同人》，柔得位得中而應乎乾曰《同人》。《同人》曰、「同人于野、亨、利涉大川」，乾行也。文明以健，中正而應，「君子」正也。唯君子爲能通天下之志。', '象曰：天與火、《同人》。君子以類族辨物。', NULL),(14, '111101', '䷍', '대유', '大有', '화천대유', '大有 元亨。', '대유는 크게 형통하다.', '彖曰：《大有》，柔得尊位大中而上下應之曰《大有》。其德剛健而文明，應乎天而時行，是以「元亨」。', '象曰：火在天上，《大有》。君子以遏惡揚善，順天休命。', NULL),(15, '001000', '䷎', '겸', '謙', '지산겸', '謙 亨。君子有終。', '겸(謙)은 형통하다. 군자는 끝이 있다.', '彖曰：《謙》「亨」。天道下際而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。《謙》、尊而光，卑而不可踰，「君子」之「終」也。', '象曰：地中有山，《謙》。君子以裒多益寡，稱物平施。', NULL),(16, '000100', '䷏', '예', '豫', '뇌지예', '豫 利建侯行師。', '예(豫)는 제후를 세우고 군대를 행하는 것이 이롭다.', '彖曰：《豫》，剛應而志行，順以動，《豫》。《豫》順以動，故天地如之，而況「建侯行師」乎？天地以順動，故日月不過而四時不忒。聖人以順動，則刑罰淸而民服，《豫》之時義大矣哉！', '象曰：雷出地奮，《豫》。先王以作樂崇德，殷薦之上帝以配祖考。', NULL),(17, '100110', '䷐', '수', '隨', '택뢰수', '隨 元亨，利貞，無咎。', '따름은 크게 형통하니, 곧게 지키면 이로우며, 허물이 없다.', '彖曰：《隨》，剛來而下柔，動而說，《隨》。大「亨、貞、無咎」而天下隨時，隨時之義大矣哉！', '象曰：澤中有雷，《隨》。君子以嚮晦入宴息。', NULL),(18, '011001', '䷑', '고', '蠱', '산풍고', '䷎）《蠱》元亨。利涉大川，先甲三日，後甲三日。', '고(蠱)는 크게 형통하다. 큰 내를 건너는 것이 이롭다. 갑일 앞 사흘, 갑일 뒤 사흘.', '彖曰：《蠱》、剛上而柔下，巽而止，《蠱》。《蠱》「元亨」，而天下治也。「利涉大川」、往有事也。「先甲三日、後甲三日」，終則有始，天行也。', '象曰：山下有風，《蠱》。君子以振民育德。', NULL),(19, '110000', '䷒', '임', '臨', '지택임', '臨 元亨，利貞。至于八月有凶。', '임(臨)은 크게 형통하니, 곧게 지키면 이롭다. 팔월에 이르면 흉함이 있다.', '彖曰：《臨》，剛浸而長，說而順，剛中而應。大「亨」以正、天之道也。「至于八月有凶」、消不久也。', '象曰：澤上有地，《臨》。君子以敎思無窮，容保民無疆。', NULL),(20, '000011', '䷓', '관', '觀', '풍지관', '觀 盥而不薦。有孚顒若。', '관(觀)은 손을 씻되 아직 올리지 않았을 때이다. 미더움이 있어 우러러보는 모습이다.', '彖曰：大觀在上，順而巽，中正以觀天下，《觀》。「盥而不薦、有孚顒若」、下觀而化也，觀天之神道而四時不忒。聖人以神道設敎而天下服矣。', '象曰：風行地上，《觀》。先王以省方觀民設敎。', NULL),(21, '100101', '䷔', '서합', '噬嗑', '화뢰서합', '噬嗑 亨。利用獄。', '서합(噬嗑)은 형통하다. 옥사를 씀이 이롭다.', '彖曰：頤中有物曰《噬嗑》。《噬嗑》而「亨」，剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，「利用獄」也。', '象曰：雷電《噬嗑》。先王以明罰勅法。', NULL),(22, '101001', '䷕', '비', '賁', '산화비', '賁 亨。小利有攸往。', '분(賁)은 형통하다. 가는 바가 있으면 작게 이롭다.', '彖曰：《賁》「亨」，柔來而文剛，故「亨」。分剛上而文柔，故「小利有攸往」。天文也。文明以止，人文也。觀乎天文以察時變，觀乎人文以化成天下。', '象曰：山下有火，《賁》。君子以明庶政，無敢折獄。', NULL),(23, '000001', '䷖', '박', '剝', '산지박', '剝 不利有攸往。', '박(剝)은 나아갈 바가 있음이 이롭지 않다.', '彖曰：《剝》、剝也。柔變剛也。「不利有攸往」、小人長也。順而止之，觀象也。君子尙消息盈虛，天行也。', '象曰：山附於地，《剝》。上以厚下安宅。', NULL),(24, '100000', '䷗', '복', '復', '지뢰복', '復 亨。出入無疾。朋來無咎。反復其道，七日來復。利有攸往。', '복(復)은 형통하다. 출입에 병폐가 없다. 벗이 오면 허물이 없다. 그 도를 반복하여 이레 만에 돌아온다. 나아갈 바가 있으면 이롭다.', '彖曰：《復》「亨」。剛反動而以順行。是以「出入無疾、朋來無咎」。「反復其道、七日來復」，天行也。「利有攸往」、剛長也。《復》、其見天地之心乎。', '象曰：雷在地中，《復》。先王以至日閉關，商旅不行，后不省方。', NULL),(25, '100111', '䷘', '무망', '无妄', '천뢰무망', '無妄 元亨，利貞。其匪正有眚，不利有攸往。', '무망은 으뜸으로 형통하고, 곧게 지키면 이롭다. 그것이 바르지 않으면 재앙이 있고, 나아갈 바가 있음이 이롭지 않다.', '彖曰：《無妄》，剛自外來而爲主於內，動而健，剛中而應。大「亨」以正，天之命也。「其匪正有眚、不利有攸往」，無妄之往何之矣？天命不祐，行矣哉！', '象曰：天下雷行，物與《無妄》。先王以茂對時育萬物。', NULL),(26, '111001', '䷙', '대축', '大畜', '산천대축', '大畜 利貞。不家食吉。利涉大川。', '대축(大畜)은 곧게 지키면 이롭다. 집에서 먹지 않으면 길하다. 큰 내를 건너는 것이 이롭다.', '彖曰：《大畜》，剛健篤實，輝光日新。其德剛上而尙賢，能止健，大正也，「不家食吉」、養賢也，「利涉大川」、應乎天也。', '象曰：天在山中，《大畜》。君子以多識前言往行以畜其德。', NULL),(27, '100001', '䷚', '이', '頤', '산뢰이', '頤 貞吉。觀頤，自求口實。', '이(頤)는 곧게 지키면 길하다. 이(頤)를 살피되, 스스로 입을 채울 것을 구한다.', '彖曰：《頤》「貞吉」，養正則吉也。「觀頤」、觀其所養也，「自求口實」、觀其自養也。天地養萬物，聖人養賢以及萬民，《頤》之時大矣哉！', '象曰：山下有雷，《頤》。君子以愼言語、節飮食。', NULL),(28, '011110', '䷛', '대과', '大過', '택풍대과', '大過 棟橈，利有攸往，亨。', '대과(大過)는 마루대가 휘어진다. 나아갈 바가 있으면 이롭고, 형통하다.', '彖曰：《大過》、大者過也。「棟橈」、本末弱也。剛過而中，巽而說，行。「利有攸往」乃「亨」。《大過》之時大矣哉！', '象曰：澤滅木，《大過》。君子以獨立不懼，遯世無悶。', NULL),(29, '010010', '䷜', '감', '習坎', '중수감', '䷇）《習坎》有孚，維心、亨。行有尙。', '습감(習坎)은 미더움이 있으니, 오직 마음이 형통하다. 행하면 숭상함이 있다.', '彖曰：《習坎》、重險也。水流而不盈。行險而不失其信。「維心亨」、乃以剛中也，「行有尙」、往有功也，天險、不可升也，地險、山川丘陵也。王公設險以守其國。險之時用大矣哉！', '象曰：水洊至，《習坎》。君子以常德行、習敎事。', NULL),(30, '101101', '䷝', '리', '離', '중화리', '離 利貞。亨。畜牝牛吉。', '리(離)는 곧게 지키면 이롭다. 형통하다. 암소를 기르면 길하다.', '彖曰：《離》、麗也。日月麗乎天，百穀草木麗乎土。重明以麗乎正，乃化成天下。柔麗乎中正，故「亨」，是以「畜牝牛吉」也。', '象曰：明兩、作《離》。大人以繼明照于四方。', NULL),(31, '001110', '䷞', '함', '咸', '택산함', '咸 亨。利貞。取女吉。', '감(咸)은 형통하다. 곧게 지키면 이롭다. 여자를 취하면 길하다.', '彖曰：《咸》、感也。柔上而剛下，二氣感應以相與，止而說，男下女，是以「亨利貞、取女吉」也。天地感而萬物化生，聖人感人心而天下和平。觀其所感而天地萬物之情可見矣。', '象曰：山上有澤，《咸》。君子以虛受人。', NULL),(32, '011100', '䷟', '항', '恆', '뇌풍항', '恒 亨。無咎。利貞。利有攸往。', '항(恒)은 형통하다. 허물이 없다. 곧게 지키면 이롭다. 나아갈 바가 있으면 이롭다.', '彖曰：《恒》、久也。剛上而柔下。雷風相與。巽而動，剛柔皆應，《恒》。「恒亨無咎利貞」、久於其道也。天地之道恒久而不已也。「利有攸往」、終則有始也。日月得天而能久照，四時變化而能久成。聖人久於其道而天下化成。觀其所恒而天地萬物之情可見矣。', '象曰：雷風《恒》。君子以立不易方。', NULL),(33, '001111', '䷠', '둔', '遯', '천산둔', '遯 亨。小利貞。', '둔(遯)은 형통하다. 작게 곧게 지키면 이롭다.', '彖曰：《遯》「亨」，遯而亨也。剛當位而應，與時行也。「小利貞」、浸而長也。《遯》之時義大矣哉！', '象曰：天下有山，《遯》。君子以遠小人，不惡而嚴。', NULL),(34, '111100', '䷡', '대장', '大壯', '뇌천대장', '大壯 利貞。', '대장(大壯)은 곧게 지키면 이롭다.', '彖曰：《大壯》、大者壯也。剛以動，故壯。《大壯》「利貞」，大者、正也。正大而天地之情可見矣。', '象曰：雷在天上，《大壯》。君子以非禮弗履。', NULL),(35, '000101', '䷢', '진', '晉', '화지진', '晉 康侯用錫馬蕃庶，晝日三接。', '진(晉)이니, 강후(康侯)가 말을 하사받되 번성하게 많이 받으며, 낮에 세 번 접견한다.', '彖曰：《晉》、進也。明出地上。順而麗乎大明，柔進而上行，是以「康侯」用「錫馬蕃庶晝日三接」也。', '象曰：明出地上，《晉》。君子以自昭明德。', NULL),(36, '101000', '䷣', '명이', '明夷', '지화명이', '明夷 利艱貞。', '명이(明夷)는 어려움을 알고 곧게 지키면 이롭다.', '彖曰：明入地中，《明夷》。內文明而外柔順，以蒙大難，文王以之。「利艱貞」、晦其明也，內難而能正其志，箕子以之。', '象曰：明入地中，《明夷》。君子以莅眾用晦而明。', NULL),(37, '101011', '䷤', '가인', '家人', '풍화가인', '家人 利女貞。', '가인(家人)은 여자가 곧게 지키면 이롭다.', '彖曰：《家人》，女正位乎內，男正位乎外。男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父、子子、兄兄、弟弟、夫夫、婦婦而家道正，正家而天下定矣。', '象曰：風自火出，《家人》。君子以言有物而行有恒。', NULL),(38, '110101', '䷥', '규', '睽', '화택규', '睽 小事吉。', '규(睽)는 작은 일에 길하다.', '彖曰：《睽》、火動而上，澤動而下。二女同居，其志不同行。說而麗乎明，柔進而上行，得中而應乎剛，是以「小事吉」。天地睽而其事同也。男女睽而其志通也。萬物睽而其事類也，睽之時用大矣哉！', '象曰：上火下澤，《睽》。君子以同而異。', NULL),(39, '001010', '䷦', '건', '蹇', '수산건', '䷎）《蹇》利西南，不利東北。利見大人。貞吉。', '준(蹇)은 서남쪽이 이롭고, 동북쪽은 이롭지 않다. 대인을 만남이 이롭다. 곧게 지키면 길하다.', '彖曰：《蹇》、難也，險在前也。見險而能止，知矣哉！《蹇》、「利西南」，往得中也，「不利東北」、其道窮也，「利見大人」、往有功也，當位「貞吉」、以正邦也。《蹇》之時用大矣哉！', '象曰：山上有水，《蹇》。君子以反身修德。', NULL),(40, '010100', '䷧', '해', '解', '뇌수해', '解 利西南。無所往，其來復吉。有攸往，夙吉。', '해(解)는 서남쪽이 이롭다. 나아갈 바가 없으면 돌아와 회복함이 길하고, 나아갈 바가 있으면 일찍 함이 길하다.', '彖曰：《解》、險以動，動而免乎險，《解》。《解》「利西南」、往得眾也，「其來復吉」、乃得中也。「有攸往夙吉」、往有功也。天地解而雷雨作，雷雨作而百果草木皆甲拆。《解》之時大矣哉！', '象曰：雷雨作，《解》。君子以赦過宥罪。', NULL),(41, '110001', '䷨', '손', '損', '산택손', '損 有孚，元吉，無咎可貞。利有攸往。曷之用，二簋可用享。', '손(損)은 미더움이 있으면 크게 길하고, 허물이 없어 곧게 지킬 만하다. 나아갈 바가 있으면 이롭다. 무엇을 쓸 것인가? 두 그릇으로도 제사 지낼 수 있다.', '彖曰：《損》、損下益上，其道上行。損而「有孚」，「元吉、無咎、可貞、利有攸往、曷之用二簋、可用享」，二簋應有時。損剛益柔有時，損益盈虛，與時偕行。', '象曰：山下有澤，《損》。君子以懲忿窒欲。', NULL),(42, '100011', '䷩', '익', '益', '풍뢰익', '益 利有攸往。利涉大川。', '익(益)은 가는 바가 있으면 이롭다. 큰 내를 건너면 이롭다.', '彖曰：《益》、損上益下，民說無疆。自上下下，其道大光。「利有攸往」、中正有慶，「利涉大川」、木道乃行。《益》動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。', '象曰：風雷《益》。君子以見善則遷，有過則改。', NULL),(43, '111110', '䷪', '쾌', '夬', '택천쾌', '夬 揚于王庭，孚號有厲，告自邑。不利卽戎，利有攸往。', '괘(夬)는 왕의 조정에서 드러내 밝히되, 미더움으로써 명령하되 위태로움이 있으니, 고을로부터 알린다. 군사를 일으키는 것은 이롭지 않고, 나아갈 바가 있으면 이롭다.', '彖曰：《夬》、決也，剛決柔也。健而說，決而和。「揚于王庭」、柔乘五剛也，「孚號有厲」、其危乃光也。「告自邑不利卽戎」、所尙乃窮也，「利有攸往」、剛長乃終也。', '象曰：澤上於天，《夬》。君子以施祿及下，居德則忌。', NULL),(44, '011111', '䷫', '구', '姤', '천풍구', '姤 女壯，勿用取女。', '구(姤)는 여자가 장성함이니, 여자를 취하는 데 쓰지 말라.', '彖曰：《姤》、遇也，柔遇剛也。「勿用取女」、不可與長也。天地相遇，品物咸章也。剛遇中正，天下大行也。《姤》之時義大矣哉！', '象曰：天下有風，《姤》。后以施命誥四方。', NULL),(45, '000110', '䷬', '췌', '萃', '택지췌', '萃 王假有廟。利見大人。亨，利貞，用大牲吉。利有攸往。', '모임(萃). 왕이 종묘에 이르렀다. 대인을 만나면 이롭다. 형통하니 곧게 지키면 이롭고, 큰 희생을 쓰면 길하다. 나아갈 바가 있으면 이롭다.', '彖曰：《萃》、聚也。順以說，剛中而應，故聚也。「王假有廟」、致孝享也，「利見大人亨」、聚以正也，「用大牲吉、利有攸往」、順天命也。觀其所聚而天地萬物之情可見矣。', '象曰：澤上於地，《萃》。君子以除戎器，戒不虞。', NULL),(46, '011000', '䷭', '승', '升', '지풍승', '升 元亨。用見大人，勿恤。南征吉。', '승(升)은 크게 형통하다. 대인을 만나는 데 쓰면 근심하지 않아도 된다. 남쪽으로 나아가면 길하다.', '彖曰：柔以時升，巽而順，剛中而應，是以大「亨」。「用見大人勿恤」、有慶也，「南征吉」、志行也。', '象曰：地中生木，升。君子以順德，積小以高大。', NULL),(47, '010110', '䷮', '곤', '困', '택수곤', '困 亨。貞大人吉，無咎。有言不信。', '곤궁하나 형통하다. 대인이 곧게 지키면 길하고 허물이 없다. 말이 있어도 믿어지지 않는다.', '彖曰：《困》、剛揜也。險以說，困而不失其所，「亨」，其唯君子乎。「貞大人吉」、以剛中也，「有言不信」、尙口乃窮也。', '象曰：澤無水，困。君子以致命遂志。', NULL),(48, '011010', '䷯', '정', '井', '수풍정', '井 改邑不改井，無喪無得。往來井井。汔至，亦未䋴井，羸其甁，凶。', '우물은 마을을 옮겨도 우물은 옮기지 않으니, 잃음도 없고 얻음도 없다. 가고 오되 우물은 우물이다. 거의 이르렀으나 아직 두레박줄이 우물에 미치지 못하고 그 병을 깨뜨리면 흉하다.', '彖曰：巽乎水而上水，《井》。井養而不窮也。「改邑不改井」、乃以剛中也。「往來井，井汔至、亦未䋴井」、未有功也，「羸其甁」、是以凶也。', '象曰：木上有水，《井》。君子以勞民勸相。', NULL),(49, '101110', '䷰', '혁', '革', '택화혁', '革 已日乃孚。元亨，利貞，悔亡。', '혁(革)은 이미 날이 지난 뒤에야 미더움이 있다. 크게 형통하고, 곧게 지키면 이로우며, 뉘우침이 없어진다.', '彖曰：《革》、水火相息，二女同居，其志不相得曰革。「已日乃孚」，革而信之。文明以說，大「亨」以正。革而當，其「悔」乃「亡」。天地革而四時成，湯武革命，順乎天而應乎人。《革》之時大矣哉！', '象曰：澤中有火，《革》。君子以治歷明時。', NULL),(50, '011101', '䷱', '정', '鼎', '화풍정', '鼎 元吉，亨。', '정(鼎)은 크게 길하고 형통하다.', '彖曰：《鼎》象也、以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎剛，是以「元亨」。', '象曰：木上有火，《鼎》。君子以正位凝命。', NULL),(51, '100100', '䷲', '진', '震', '중뇌진', '震 亨。震來虩虩，笑言啞啞，震驚百里，不喪匕鬯。', '진(震)은 형통하다. 진이 올 때 두려워하고, 웃으며 말하기를 화락하며, 진이 백 리를 놀라게 하나, 비(匕)와 창(鬯)을 잃지 않는다.', '彖曰：《震》「亨」。「震來虩虩」、恐致福也，「笑言啞啞」、後有則也，「震驚百里」、驚遠而懼邇也。不喪匕鬯、出可以守宗廟社稷，以爲祭主也。', '象曰：洊雷、《震》。君子以恐懼修省。', NULL),(52, '001001', '䷳', '간', '艮', '중산간', '艮 其背，不獲其身，行其庭，不見其人，無咎。', '간(艮)은 그 등을 그치게 함이니, 그 몸을 얻지 못하고, 그 뜰을 행하되 그 사람을 보지 못하면 허물이 없다.', '彖曰：《艮》、止也。時止則止，時行則行，動靜不失其時，其道光明。艮其止，止其所也。上下敵應，不相與也。是以不獲其身、行其庭不見其人，無咎也。', '象曰：兼山，《艮》。君子以思不出其位。', NULL),(53, '001011', '䷴', '점', '漸', '풍산점', '漸 女歸吉。利貞。', '점진적으로 나아감이니, 여자가 시집가면 길하다. 곧게 지키면 이롭다.', '彖曰：《漸》之進也。「女歸吉」也，進得位，往有功也。進以正，可以正邦也。其位、剛得中也。止而巽，動不窮也。', '象曰：山上有木，《漸》。君子以居賢德善俗。', NULL),(54, '110100', '䷵', '귀매', '歸妹', '뇌택귀매', '歸妹 征凶，無攸利。', '귀매는 나아가면 흉하니, 이로운 바가 없다.', '彖曰：《歸妹》、天地之大義也。天地不交而萬物不興。《歸妹》、人之終始也。說以動，所歸妹也。「征凶」、位不當也，「無攸利」、柔乘剛也。', '象曰：澤上有雷，《歸妹》。君子以永終知敝。', NULL),(55, '101100', '䷶', '풍', '豐', '뇌화풍', '豊 亨，王假之。勿憂，宜日中。', '풍은 형통하니, 왕이 이에 이른다. 근심하지 말고, 마땅히 해가 한가운데 있는 것과 같이 하라.', '彖曰：《豊》、大也。明以動，故《豊》。「王假之」、尙大也。「勿憂宜日中」、宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎，況於鬼神乎？', '象曰：雷電皆至，《豊》。君子以折獄致刑。', NULL),(56, '001101', '䷷', '여', '旅', '화산여', '旅 小亨。旅貞吉。', '여(旅)는 작게 형통하다. 나그네로서 곧게 지키면 길하다.', '彖曰：《旅》「小亨」，柔得中乎外而順乎剛，止而麗乎明，是以「小亨旅貞吉」也。旅之時義大矣哉！', '象曰：山上有火，《旅》。君子以明愼用刑而不留獄。', NULL),(57, '011011', '䷸', '손', '巽', '중풍손', '巽 小亨。利有攸往。利見大人。', '손(巽)은 작게 형통하다. 나아갈 바가 있으면 이롭다. 대인을 만나면 이롭다.', '彖曰：重巽以申命。剛巽乎中正而志行。柔皆順乎剛，是以「小亨、利有攸往、利見大人」。', '象曰：隨風，《巽》。君子以申命行事。', NULL),(58, '110110', '䷹', '태', '兌', '중택태', '兌 亨。利貞。', '태(兌)는 형통하다. 곧게 지키면 이롭다.', '彖曰：《兌》、說也。剛中而柔外。說以「利貞」，是以順乎天而應乎人。說以先民，民忘其勞。說以犯難，民忘其死。說之大，民勸矣哉！', '象曰：麗澤，《兌》。君子以朋友講習。', NULL),(59, '010011', '䷺', '환', '渙', '풍수환', '渙 亨。王假有廟。利涉大川，利貞。', '환(渙)은 형통하다. 왕이 종묘에 이른다. 큰 내를 건너는 것이 이롭고, 곧게 지키면 이롭다.', '彖曰：《渙》「亨」，剛來而不窮，柔得位乎外而上同。「王假有廟」、王乃在中也，「利涉大川」、乘木有功也。', '象曰：風行水上，《渙》。先王以享于帝，立廟。', NULL),(60, '110010', '䷻', '절', '節', '수택절', '節 亨。苦節，不可貞。', '절(節)은 형통하다. 괴로운 절제는 곧게 지킬 수 없다.', '彖曰：《節》「亨」。剛柔分而剛得中。「苦節不可貞」、其道窮也。說以行險，當位以節，中正以通。天地節而四時成。節以制度，不傷財，不害民。', '象曰：澤上有水，《節》。君子以制數度，議德行。', NULL),(61, '110011', '䷼', '중부', '中孚', '풍택중부', '中孚 豚魚，吉。利涉大川，利貞。', '중부는 돼지와 물고기에게 미더움이 있으니 길하다. 큰 내를 건너는 데 이롭고, 곧게 지키면 이롭다.', '彖曰：《中孚》、柔在內而剛得中，說而巽，孚，乃化邦也。「豚魚吉」、信及豚魚也，「利涉大川」、乘木舟虛也，中孚以「利貞」、乃應乎天也。', '象曰：澤上有風，《中孚》。君子以議獄緩死。', NULL),(62, '001100', '䷽', '소과', '小過', '뇌산소과', '小過 亨。利貞。可小事，不可大事。飛鳥遺之音，不宜上，宜下，大吉。', '소과는 형통하다. 곧게 지키면 이롭다. 작은 일은 가하나, 큰일은 가하지 않다. 나는 새가 남긴 소리는 위로 가는 것이 마땅하지 않고 아래로 가는 것이 마땅하니, 크게 길하다.', '彖曰：《小過》「亨」、小者過而亨也。過以「利貞」、與時行也。柔得中，是以「小事吉」也。剛失位而不中，是以「不可大事」也。有「飛鳥」之象焉，「飛鳥遺之音、不宜上、宜下、大吉」、上逆而下順也。', '象曰：山上有雷，《小過》。君子以行過乎恭，喪過乎哀，用過乎儉。', NULL),(63, '101010', '䷾', '기제', '既濟', '수화기제', '旣濟 亨。小利貞。初吉終亂。', '기제는 형통하다. 작은 것이 곧게 지키면 이롭다. 처음은 길하나 마침내 어지럽다.', '彖曰：《旣濟》「亨」，小者亨也。「利貞」。剛柔正而位當也。「初吉」、柔得中也。「終」止則「亂」，其道窮也。', '象曰：水在火上，《旣濟》。君子以思患而豫防之。', NULL),(64, '010101', '䷿', '미제', '未濟', '화수미제', '未濟 亨。小狐汔濟，濡其尾，無攸利。', '미제(未濟)는 형통하다. 작은 여우가 거의 건너려 하나 그 꼬리를 적시니, 이로운 바가 없다.', '彖曰：《未濟》「亨」、柔得中也。「小狐汔濟」、未出中也。「濡其尾、無攸利」、不續終也。雖不當位、剛柔應也。', '象曰：火在水上，《未濟》。君子以愼辨物居方。', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lines (id, hexagram_id, line_number, statement_text, statement_ko, small_xiang_text) VALUES (1, 1, 1, '初九 潛龍勿用。', '초구는 잠긴 용이니 쓰지 말라.', '「潛龍勿用」、陽在下也。'),(2, 1, 2, '九二 見龍在田，利見大人。', '구이. 용이 밭에 나타나니, 대인을 만남이 이롭다.', '「見龍在田」、德施普也。'),(3, 1, 3, '九三 君子終日乾乾，夕惕若厲。無咎。', '구삼. 군자가 종일토록 건건하고, 저녁에 두려워하여 위태로운 듯하면 허물이 없다.', '「終日乾乾」、反復道也。'),(4, 1, 4, '九四 或躍在淵，無咎。', '구사. 혹 뛰어오르고 혹 연못에 있으니, 허물이 없다.', '「或躍在淵」、進「無咎」也。'),(5, 1, 5, '九五 飛龍在天，利見大人。', '구오. 나는 용이 하늘에 있으니, 대인을 만남이 이롭다.', '「飛龍在天」、「大人」造也。'),(6, 1, 6, '上九 亢龍，有悔。', '상구, 높이 오른 용이니 뉘우침이 있다.', '「亢龍有悔」、盈不可久也。'),(7, 1, 7, '用九 見群龍無首，吉。', '용구는 뭇 용이 머리가 없음을 보니, 길하다.', '「用九」、天德不可爲首也。'),(8, 2, 1, '初六 履霜、堅氷至。', '초육. 서리를 밟으면 단단한 얼음이 이른다.', '象曰：「履霜堅氷」、陰始凝也。馴致其道，至「堅氷」也。'),(9, 2, 2, '六二 直、方、大，不習無不利。', '육이는 곧고, 모나고, 크니, 익히지 않아도 이롭지 않음이 없다.', '象曰：六二之動、「直」以「方」也，「不習無不利」、地道光也。'),(10, 2, 3, '六三 含章可貞，或從王事，無成有終。', '육삼은 아름다움을 머금고 있으면 곧게 지킬 수 있으니, 혹 왕의 일을 따르되 이룸이 없고 마침이 있다.', '象曰：「含章可貞」、以時發也。「或從王事」、知光大也。'),(11, 2, 4, '六四 括囊，無咎無譽。', '육사. 주머니를 묶으면 허물도 없고 명예도 없다.', '象曰：「括囊無咎」、愼不害也。'),(12, 2, 5, '六五 黃裳元吉。', '육오는 누런 치마이니 크게 길하다.', '象曰：「黃裳元吉」、文在中也。'),(13, 2, 6, '上六 龍戰于野，其血玄黃。', '상육, 용이 들에서 싸우니, 그 피가 검고 누렇다.', '象曰：「龍戰于野」，其道窮也。'),(14, 2, 7, '用六 利永貞。', '용육. 영원히 곧게 지키면 이롭다.', '象曰：「用六永貞」，以大終也。'),(15, 3, 1, '初九 磐桓。利居貞。利建侯。', '초구는 머뭇거린다. 머물러 곧게 지키면 이롭다. 제후를 세우면 이롭다.', '象曰：雖「磐桓」，志行正也。以貴下賤，大得民也。'),(16, 3, 2, '六二 屯如邅如，乘馬班如。匪寇，婚媾。女子貞不字，十年乃字。', '육이는 준하고 전하며, 말을 타고 반하다. 도적이 아니라 혼구이다. 여자가 곧게 지켜 아이를 낳지 않다가, 십 년이 되어서야 아이를 낳는다.', '象曰：六二之難、乘剛也，「十年乃字」、反常也。'),(17, 3, 3, '六三 卽鹿無虞，惟入于林中，君子幾不如舍，往吝。', '육삼. 사슴을 쫓되 우인이 없으니, 다만 숲속으로 들어갈 뿐이다. 군자는 기미를 보아 버리는 것만 못하니, 나아가면 부끄러움이 있다.', '象曰：「卽鹿無虞」以從禽也。「君子舍」之，「往吝」窮也。'),(18, 3, 4, '六四 乘馬班如，求婚媾。往吉，無不利。', '육사. 말을 타고 머뭇거린다. 혼구를 구한다. 나아가면 길하고, 이롭지 않음이 없다.', '象曰：「求」而「往」、明也。'),(19, 3, 5, '九五 屯其膏，小貞吉，大貞凶。', '구오는 그 기름을 준(屯)하게 하니, 작게 곧게 지키면 길하고 크게 곧게 지키면 흉하다.', '象曰：「屯其膏」、施未光也。'),(20, 3, 6, '上六 乘馬班如，泣血漣如。', '상육. 말을 타고 가려 하나 뒤섞여 나아가지 못하고, 피눈물을 흘리며 줄줄 흐르게 한다.', '象曰：「泣血漣如」，何可長也？'),(21, 4, 1, '初六 發蒙，利用刑人，用說桎梏，以往吝。', '초육. 몽매함을 계발함에, 형벌을 씀이 이로우니, 질곡을 벗기는 것이다. 이로써 나아가면 부끄러움이 있다.', '象曰：「利用刑人」、以正法也。'),(22, 4, 2, '九二 包蒙，吉。納婦吉。子克家。', '구이. 몽매함을 포용하니 길하다. 부인을 받아들이면 길하다. 자식이 집안을 다스린다.', '象曰：「子克家」、剛柔接也。'),(23, 4, 3, '六三 勿用取女，見金夫，不有躬。無攸利。', '육삼. 여자를 취하는 데 쓰지 말라. 금을 가진 남자를 보면 몸을 보유하지 못한다. 이로운 바가 없다.', '象曰：「勿用取女」、行不順也。'),(24, 4, 4, '六四 困蒙，吝。', '육사는 몽매함에 곤궁하니, 부끄럽다.', '象曰：「困蒙」之「吝」、獨遠實也。'),(25, 4, 5, '六五 童蒙，吉。', '육오. 동몽이니, 길하다.', '象曰：「童蒙」之吉、順以巽也。'),(26, 4, 6, '上九 擊蒙，不利爲寇，利禦寇。', '상구. 몽매함을 친다. 도적이 되는 것은 이롭지 않고, 도적을 막는 것은 이롭다.', '象曰：「利」用「禦寇」，上下順也。'),(27, 5, 1, '初九 需于郊，利用恒，無咎。', '초구는 들에서 기다린다. 항상함을 지키면 이로우니, 허물이 없다.', '象曰：「需于郊」、不犯難行也。「利用恒無咎」、未失常也。'),(28, 5, 2, '九二 需于沙，小有言，終吉。', '구이는 모래에서 기다린다. 조금 말이 있으나 마침내 길하다.', '象曰：「需于沙」、行在中也。雖「小有言」、以「吉」「終」也。'),(29, 5, 3, '九三 需于泥，致寇至。', '구삼은 진흙에서 기다리니, 도적이 이르게 한다.', '象曰：「需于泥」、災在外也。自我「致寇」、敬愼不敗也。'),(30, 5, 4, '六四 需于血，出自穴。', '육사는 피에서 기다리다가 구멍에서 나온다.', '象曰：「需于血」、順以聽也。'),(31, 5, 5, '九五 需于酒食，貞吉。', '구오는 술과 음식에서 기다리니, 곧게 지키면 길하다.', '象曰：「酒食貞吉」、以中正也。'),(32, 5, 6, '上六 入于穴，有不速之客三人來，敬之終吉。', '상육은 구덩이에 들어가니, 부르지 않은 손님 세 사람이 온다. 공경하면 마침내 길하다.', '象曰：「不速之客來、敬之終吉」，雖不當位，未大失也。'),(33, 6, 1, '初六 不永所事，小有言，終吉。', '초육은 일을 오래 끌지 않으니, 조금 말이 있으나 마침내 길하다.', '象曰：「不永所事」、訟不可長也。雖「小有言」、其辯明也。'),(34, 6, 2, '九二 不克訟，歸而逋其邑，人三百戶無眚。', '구이, 송사를 이기지 못하고 돌아가 그 읍에서 달아나니, 삼백 호의 사람들이 재앙이 없다.', '象曰：「不克訟」、「歸逋」竄也。自下訟上，患至掇也。'),(35, 6, 3, '六三 食舊德，貞厲，終吉。或從王事無成。', '육삼은 옛 덕을 먹으니, 곧게 지키되 위태롭지만 마침내 길하다. 혹 왕의 일을 따르되 이루지 못한다.', '象曰：「食舊德」、從上「吉」也。'),(36, 6, 4, '九四 不克訟，復卽命，渝。安貞吉。', '구사는 송사에서 이기지 못하고, 돌아와 명을 따르며, 바뀐다. 편안히 곧게 지키면 길하다.', '象曰：「復卽命、渝」、「安貞」不失也。'),(37, 6, 5, '九五 訟元吉。', '구오. 송(訟)이 크게 길하다.', '象曰：「訟元吉」、以中正也。'),(38, 6, 6, '上九 或錫之鞶、帶，終朝三褫之。', '상구. 혹 띠를 하사받으나, 아침이 끝나기 전에 세 번 빼앗긴다.', '象曰：以訟受服、亦不足敬也。'),(39, 7, 1, '初六 師出以律，否臧凶。', '초육. 군대가 나아갈 때 법도로써 하니, 그렇지 않으면 좋다 하더라도 흉하다.', '象曰：「師出以律」，失律「凶」也。'),(40, 7, 2, '九二 在師中，吉、無咎，王三錫命。', '구이는 군대의 가운데에 있으니, 길하고 허물이 없으며, 왕이 세 번 명을 내린다.', '象曰：「在師中吉」、承天寵也，「王三錫命」、懷萬邦也。'),(41, 7, 3, '六三 師或輿尸，凶。', '육삼. 군대가 혹 시체를 싣고 오니, 흉하다.', '象曰：「師或輿尸」、大無功也。'),(42, 7, 4, '六四 師左次，無咎。', '육사는 군대가 왼쪽으로 머무르니, 허물이 없다.', '象曰：「左次無咎」、未失常也。'),(43, 7, 5, '六五 田有禽。利執言，無咎。長子帥師，弟子輿尸，貞凶。', '육오. 밭에 짐승이 있다. 말을 잡아 집행하면 허물이 없다. 장자가 군대를 거느리면, 제자가 시체를 실으니 곧게 지켜도 흉하다.', '象曰：「長子帥師」、以中行也，「弟子輿尸」、使不當也。'),(44, 7, 6, '上六 大君有命，開國承家，小人勿用。', '상육. 큰 임금이 명을 내려 나라를 열고 집을 이어받게 하되, 소인은 쓰지 말라.', '象曰：「大君有命」、以正功也，「小人勿用」、必亂邦也。'),(45, 8, 1, '初六 有孚比之，無咎。有孚盈缶，終來，有他吉。', '초육. 미더움이 있어 친하게 지내면 허물이 없다. 미더움이 있어 질그릇에 가득하면, 마침내 오니 다른 이가 있어도 길하다.', '象曰：《比》之初六、「有他吉」也。'),(46, 8, 2, '六二 比之自內，貞吉。', '육이는 안으로부터 친하니, 곧게 지키면 길하다.', '象曰：「比之自內」、不自失也。'),(47, 8, 3, '六三 比之匪人。', '육삼은 아닌 사람과 친하다.', '象曰：「比之匪人」、不亦傷乎？'),(48, 8, 4, '六四 外比之，貞吉。', '육사. 밖으로 친하니, 곧게 지키면 길하다.', '象曰：「外比」於賢、以從上也。'),(49, 8, 5, '九五 顯比，王用三驅，失前禽，邑人不誡，吉。', '구오. 드러나게 친하니, 왕이 세 방향으로 몰이하여 앞으로 가는 짐승을 놓치고, 읍의 사람들에게 경계하지 않으니, 길하다.', '象曰：「顯比」之「吉」、位正中也，舍逆取順、「失前禽」也，「邑人不誡」、上使中也。'),(50, 8, 6, '上六 比之無首，凶。', '상육. 친함에 머리가 없으니 흉하다.', '象曰：「比之無首」、無所終也。'),(51, 9, 1, '初九 復自道，何其咎，吉。', '초구는 스스로 도로 돌아오니, 어찌 그 허물이 있으리오. 길하다.', '象曰：「復自道」、其義「吉」也。'),(52, 9, 2, '九二 牽復，吉。', '구이는 서로 이끌어 돌아오니, 길하다.', '象曰：「牽復」在中、亦不自失也。'),(53, 9, 3, '九三 輿說輻。夫妻反目。', '구삼. 수레가 바퀴살을 벗긴다. 부부가 눈을 뒤집는다.', '象曰：「夫妻反目」、不能正室也。'),(54, 9, 4, '六四 有孚血去惕出，無咎。', '육사. 미더움이 있으면 피가 물러가고 두려움이 나가니, 허물이 없다.', '象曰：「有孚惕出」、上合志也。'),(55, 9, 5, '九五 有孚攣如，富以其隣。', '구오. 미더움이 있어 연결되니, 그 이웃과 더불어 부유하다.', '象曰：「有孚攣如」、不獨富也。'),(56, 9, 6, '上九 旣雨旣處，尙德載。婦貞厲。月幾望，君子征凶。', '상구. 이미 비가 내리고 이미 머물렀으니, 덕을 숭상하여 가득 찼다. 부인이 곧게 지키면 위태롭다. 달이 거의 보름이 되니, 군자가 나아가면 흉하다.', '象曰：「旣雨旣處」、「德」積「載」也。「君子征凶」、有所疑也。'),(57, 10, 1, '初九 素履往，無咎。', '초구는 본바탕 그대로 밟고 나아가면 허물이 없다.', '象曰：「素履」之「往」、獨行願也。'),(58, 10, 2, '九二 履道坦坦，幽人貞吉。', '구이는 도를 밟음이 평탄하고 평탄하니, 그윽한 사람이 곧게 지키면 길하다.', '象曰：「幽人貞吉」、中不自亂也。'),(59, 10, 3, '六三 眇能視，跛能履，履虎尾，咥人凶。武人爲于大君。', '육삼은 애꾸눈이지만 볼 수 있고, 절름발이지만 밟을 수 있으나, 호랑이 꼬리를 밟으면 사람을 물어 흉하다. 무인이 대군이 된다.', '象曰：「眇能視」、不足以有明也，「跛能履」、不足以與行也。「咥人」之「凶」、位不當也，「武人爲于大君」、志剛也。'),(60, 10, 4, '九四 履虎尾愬愬，終吉。', '구사. 호랑이 꼬리를 밟되 두려워하면, 마침내 길하다.', '象曰：「愬愬終吉」、志行也。'),(61, 10, 5, '九五 夬履貞厲。', '구오는 결단하여 밟으니 곧게 지켜도 위태롭다.', '象曰：「夬履貞厲」、位正當也。'),(62, 10, 6, '上九 視履考祥，其旋，元吉。', '상구는 밟은 바를 살피고 상서로움을 살핀다. 그 돌아봄이 으뜸으로 길하다.', '象曰：「元吉」在上、大有慶也。'),(63, 11, 1, '初九 拔茅茹以其彙。征吉。', '초구는 띠풀을 뽑으니 그 뿌리가 엮여 있어 그 무리와 함께한다. 나아가면 길하다.', '象曰：「拔茅征吉」、志在外也。'),(64, 11, 2, '九二 包荒，用馮河，不遐遺。朋亡，得尙于中行。', '구이는 거친 것을 포용하고, 강을 맨몸으로 건너는 용기를 쓰며, 먼 것을 버리지 않고, 무리를 없애면, 중도를 행함에서 숭상함을 얻는다.', '象曰：「包荒、得尙于中行」，以光大也。'),(65, 11, 3, '九三 無平不陂，無往不復。艱貞，無咎。勿恤其孚，于食有福。', '구삼. 평평하지 않음이 없으면 기울지 않음이 없고, 가지 않음이 없으면 돌아오지 않음이 없다. 어렵게 여기며 곧게 지키면 허물이 없다. 그 미더움을 근심하지 말라. 먹는 것에 복이 있다.', '象曰：「無往不復」、天地際也。'),(66, 11, 4, '六四 翩翩，不富以其隣，不戒以孚。', '육사는 펄펄 날아가니, 부유하지 않아도 그 이웃과 함께하고, 경계하지 않아도 미더움으로써 한다.', '象曰：「翩翩不富」、皆失實也，「不戒以孚」、中心願也。'),(67, 11, 5, '六五 帝乙歸妹，以祉，元吉。', '육오. 제을이 누이를 시집보내니, 이로써 복을 받아 크게 길하다.', '象曰：「以祉元吉」、中以行願也。'),(68, 11, 6, '上六 城復于隍，勿用師，自邑告命、貞吝。', '상육. 성이 무너져 해자로 돌아간다. 군대를 쓰지 말라. 고을로부터 명을 알린다. 곧게 지켜도 부끄럽다.', '象曰：「城復于隍」、其命亂也。'),(69, 12, 1, '初六 拔茅茹，以其彙。貞吉亨。', '초육. 띠풀을 뽑으니 그 뿌리가 따라 나온다. 그 무리로써 한다. 곧게 지키면 길하고 형통하다.', '象曰：「拔茅貞吉」、志在君也。'),(70, 12, 2, '六二 包承，小人吉，大人否。亨。', '육이는 포용하여 받들면, 소인에게는 길하나 대인은 막힌다. 형통하다.', '象曰：「大人否亨」、不亂群也。'),(71, 12, 3, '六三 包羞。', '육삼은 부끄러움을 품는다.', '象曰：「包羞」、位不當也。'),(72, 12, 4, '九四 有命，無咎，疇離祉。', '구사. 명이 있으면 허물이 없고, 무리가 복에 붙는다.', '象曰：「有命無咎」、志行也。'),(73, 12, 5, '九五 休否，大人吉。其亡其亡，繫于苞桑。', '구오. 막힘을 쉬게 하니, 대인이면 길하다. 그 망함이여 그 망함이여, 뽕나무 덤불에 매어 두어야 한다.', '象曰：「大人」之「吉」、位正當也。'),(74, 12, 6, '上九 傾否，先否後喜。', '상구, 부(否)를 기울인다. 먼저 부(否)하고 뒤에 기쁨이 있다.', '象曰：「否」終則「傾」、何可長也。'),(75, 13, 1, '初九 同人于門，無咎。', '초구는 문에서 사람들과 함께하니, 허물이 없다.', '象曰：「出門同人」，又誰「咎」也。'),(76, 13, 2, '六二 同人于宗，吝。', '육이는 종족과 더불어 사람들과 함께한다. 부끄럽다.', '象曰：「同人于宗」、「吝」道也。'),(77, 13, 3, '九三 伏戎于莽，升其高陵，三歲不興。', '구삼. 병사를 풀숲에 숨기고, 그 높은 언덕에 올라가나, 삼 년이 되도록 일어나지 못한다.', '象曰：「伏戎于莽」、敵剛也，「三歲不興」、安行也。'),(78, 13, 4, '九四 乘其墉，弗克攻，吉。', '구사. 그 담에 올랐으나 이기지 못하니 길하다.', '象曰：「乘其墉」、義「弗克」也。其「吉」、則困而反則也。'),(79, 13, 5, '九五 同人先號咷而後笑，大師克，相遇。', '구오는 사람과 함께하되 먼저 부르짖고 울부짖다가 뒤에 웃으니, 큰 군대로 이긴 뒤에 서로 만난다.', '象曰：「同人」之「先」以中直也。「大師相遇」、言相「克」也。'),(80, 13, 6, '上九 同人于郊，無悔。', '상구, 교외에서 사람들과 함께하니 뉘우침이 없다.', '象曰：「同人于郊」、志未得也。'),(81, 14, 1, '初九 無交害，匪咎、艱則無咎。', '초구는 사귐에 해가 없으니, 허물이 아니다. 어려움을 생각하면 허물이 없다.', '象曰：《大有》初九，無交害也。'),(82, 14, 2, '九二 大車以載，有攸往，無咎。', '구이는 큰 수레로써 실으니, 나아갈 바가 있어도 허물이 없다.', '象曰：「大車以載」、積中不敗也。'),(83, 14, 3, '九三 公用亨于天子，小人弗克。', '구삼. 공이 천자에게 형통함을 쓰니, 소인은 이기지 못한다.', '象曰：「公用亨于天子」、「小人」害也。'),(84, 14, 4, '九四 匪其彭，無咎。', '구사. 그 성함이 아니면 허물이 없다.', '象曰：「匪其彭、無咎」、明辨晢也。'),(85, 14, 5, '六五 厥孚交如，威如吉。', '육오. 그 미더움이 사귀는 듯하고, 위엄이 있으면 길하다.', '象曰：「厥孚交如」、信以發志也，「威如」之「吉」、易而無備也。'),(86, 14, 6, '上九 自天祐之，吉無不利。', '상구. 하늘로부터 도우심을 받으니, 길하고 이롭지 않음이 없다.', '象曰：《大有》上「吉」、「自天祐」也。'),(87, 15, 1, '初六 謙謙君子，用涉大川，吉。', '초육은 겸손하고 겸손한 군자이니, 큰 내를 건너는 데 쓰면 길하다.', '象曰：「謙謙君子」、卑以自牧也。'),(88, 15, 2, '六二 鳴謙，貞吉。', '육이는 겸손함을 드러내니, 곧게 지키면 길하다.', '象曰：「鳴謙貞吉」、中心得也。'),(89, 15, 3, '九三 勞謙，君子有終、吉。', '구삼. 수고로움 속에서 겸손함이니, 군자가 끝을 이루면 길하다.', '象曰：「勞謙君子」、萬民服也。'),(90, 15, 4, '六四 無不利，撝謙。', '육사. 이롭지 않음이 없으니, 겸손함을 펼친다.', '象曰：「無不利、撝謙」、不違則也。'),(91, 15, 5, '六五 不富以其隣，利用侵伐，無不利。', '육오. 부유하지 않으나 그 이웃과 함께하니, 침벌을 행하면 이롭고, 이롭지 않음이 없다.', '象曰：「利用侵伐」、征不服也。'),(92, 15, 6, '上六 鳴謙，利用行師征邑國。', '상육, 겸손함을 소리 내어 드러낸다. 군대를 일으켜 읍국을 정벌하는 데 쓰면 이롭다.', '象曰：「鳴謙」、志未得也。可「用行師」、征邑國也。'),(93, 16, 1, '初六 鳴豫，凶。', '초육은 울며 즐거워하니, 흉하다.', '象曰：「初六鳴豫」、志窮「凶」也。'),(94, 16, 2, '六二 介于石，不終日，貞吉。', '육이는 돌처럼 굳게 지키니, 하루를 마치지 않고서 곧게 지키면 길하다.', '象曰：「不終日貞吉」、以中正也。'),(95, 16, 3, '六三 盱豫，悔，遲有悔。', '육삼은 우러러보며 즐거워하니, 뉘우침이 있다. 더디면 뉘우침이 있다.', '象曰：「盱豫有悔」、位不當也。'),(96, 16, 4, '九四 由豫，大有得，勿疑。朋盍簪。', '구사. 예로 말미암아 크게 얻음이 있으니, 의심하지 말라. 벗들이 모여든다.', '象曰：「由豫大有得」、志大行也。'),(97, 16, 5, '六五 貞疾，恒不死。', '육오는 곧게 지키나 병이 있으되, 항상 죽지는 않는다.', '象曰：「六五貞疾」、乘剛也，「恒不死」、中未亡也。'),(98, 16, 6, '上六 冥豫成，有渝、無咎。', '상육은 어두운 즐거움이 이루어졌으나, 변함이 있으면 허물이 없다.', '象曰：「冥豫」在「上」、何可長也？'),(99, 17, 1, '初九 官有渝，貞吉，出門交有功。', '초구는 주관하는 바에 변화가 있으니, 곧게 지키면 길하다. 문을 나가 사귀면 공이 있다.', '象曰：「官有渝」、從正「吉」也，「出門交有功」、不失也。'),(100, 17, 2, '六二 係小子，失丈夫。', '육이는 소자(小子)에게 매이면 장부(丈夫)를 잃는다.', '象曰：「係小子」、弗兼與也。'),(101, 17, 3, '六三 係丈夫，失小子，隨有求、得。利居貞。', '육삼은 장부에게 매이고 소자를 잃는다. 따름에 구함이 있으면 얻는다. 곧게 지키면 이롭다.', '象曰：「係丈夫」、志舍下也。'),(102, 17, 4, '九四 隨有獲，貞凶。有孚在道，以明，何咎？', '구사. 따름에 얻음이 있으면 곧게 지켜도 흉하다. 미더움이 있어 도에 있으면서 밝으면 무슨 허물이 있겠는가?', '象曰：「隨有獲」、其義「凶」也，「有孚在道」、「明」功也。'),(103, 17, 5, '九五 孚于嘉、吉。', '구오. 아름다움에 미더우면 길하다.', '象曰：「孚于嘉吉」、位正中也。'),(104, 17, 6, '上六 拘係之乃從，維之，王用亨于西山。', '상육. 붙잡아 묶으니 이에 따르고, 얽어매니, 왕이 서산에서 형통함을 이룬다.', '象曰：「拘係之」、上窮也。'),(105, 18, 1, '初六 幹父之蠱，有子，考無咎，厲終吉。', '초육은 아버지의 고(蠱)를 바로잡으니, 자식이 있으면 아버지가 허물이 없고, 위태로우나 마침내 길하다.', '象曰：「幹父之蠱」、意承「考」也。'),(106, 18, 2, '九二 幹母之蠱，不可貞。', '구이는 어머니의 고를 바로잡으니, 곧게 지킬 수 없다.', '象曰：「幹母之蠱」、得中道也。'),(107, 18, 3, '九三 幹父之蠱，小有悔，無大咎。', '구삼. 아버지의 고(蠱)를 바로잡으니, 조금 뉘우침이 있으나 큰 허물은 없다.', '象曰：「幹父之蠱」、終「無咎」也。'),(108, 18, 4, '六四 裕父之蠱，往見吝。', '육사는 아버지의 고를 너그럽게 함이니, 나아가면 부끄러움을 보리라.', '象曰：「裕父之蠱」、往未得也。'),(109, 18, 5, '六五 幹父之蠱，用譽。', '육오는 아버지의 고를 바로잡으니, 명예를 얻는다.', '象曰：「幹父用譽」、承以德也。'),(110, 18, 6, '上九 不事王侯，高尙其事。', '상구는 왕후를 섬기지 않고, 그 일을 높이고 숭상한다.', '象曰：「不事王侯」、志可則也。'),(111, 19, 1, '初九 咸臨，貞吉。', '초구는 함께 임하니, 곧게 지키면 길하다.', '象曰：「咸臨貞吉」、志行正也。'),(112, 19, 2, '九二 咸臨吉，無不利。', '구이. 함께 임하니 길하고, 이롭지 않음이 없다.', '象曰：「咸臨吉無不利」、未順命也。'),(113, 19, 3, '六三 甘臨，無攸利；旣憂之，無咎。', '육삼. 달게 임하니, 이로울 바가 없다. 이미 이를 근심하면 허물이 없다.', '象曰：「甘臨」、位不當也，「旣憂之」、「咎」不長也。'),(114, 19, 4, '六四 至臨，無咎。', '육사는 지극히 임하니, 허물이 없다.', '象曰：「至臨無咎」、位當也。'),(115, 19, 5, '六五 知臨，大君之宜，吉。', '육오. 지혜로 임하니, 대군이 마땅히 할 바이다. 길하다.', '象曰：「大君之宜」、行中之謂也。'),(116, 19, 6, '上六 敦臨吉，無咎。', '상육은 돈독하게 임하니 길하고, 허물이 없다.', '象曰：「敦臨」之「吉」、志在內也。'),(117, 20, 1, '初六 童觀，小人無咎，君子吝。', '초육은 어린아이처럼 봄이니, 소인은 허물이 없으나 군자는 부끄럽다.', '象曰：「初六童觀」、「小人」道也。'),(118, 20, 2, '六二 闚觀，利女貞。', '육이는 엿보는 관찰이니, 여자가 곧게 지키면 이롭다.', '象曰：「闚觀女貞」、亦可醜也。'),(119, 20, 3, '六三 觀我生進退。', '육삼. 나의 생을 관찰하여 나아가고 물러난다.', '象曰：「觀我生進退」、未失道也。'),(120, 20, 4, '六四 觀國之光，利用賓于王。', '육사는 나라의 빛을 본다. 왕에게 빈객이 되는 데 쓰면 이롭다.', '象曰：「觀國之光」、尙「賓」也。'),(121, 20, 5, '九五 觀我生，君子無咎。', '구오. 나의 생을 관찰하니, 군자라면 허물이 없다.', '象曰：「觀我生」、觀民也。'),(122, 20, 6, '上九 觀其生，君子無咎。', '상구는 그 생을 관찰하니, 군자이면 허물이 없다.', '象曰：「觀其生」、志未平也。'),(123, 21, 1, '初九 屨校滅趾，無咎。', '초구는 나무 칼을 신어 발가락을 덮으니, 허물이 없다.', '象曰：「屨校滅趾」、不行也。'),(124, 21, 2, '六二 噬膚滅鼻，無咎。', '육이는 살을 깨물어 코가 잠기니, 허물이 없다.', '象曰：「噬膚滅鼻」、乘剛也。'),(125, 21, 3, '六三 噬腊肉遇毒，小吝，無咎。', '육삼은 말린 고기를 씹다가 독을 만나니, 조금 부끄러우나 허물은 없다.', '象曰：「遇毒」、位不當也。'),(126, 21, 4, '九四 噬乾胏，得金矢。利艱貞、吉。', '구사는 마른 고기와 뼈를 씹어서 쇠화살을 얻는다. 어려움을 곧게 지키면 이로우니 길하다.', '象曰：「利艱貞吉」、未光也。'),(127, 21, 5, '六五 噬乾肉，得黃金。貞厲無咎。', '육오는 마른 고기를 씹어 황금을 얻는다. 곧게 지키되 위태로움을 품으면 허물이 없다.', '象曰：「貞厲無咎」、得當也。'),(128, 21, 6, '上九 何校滅耳，凶。', '상구, 칼을 메어 귀를 가리니 흉하다.', '象曰：「何校滅耳」、聰不明也。'),(129, 22, 1, '初九 賁其趾，舍車而徒。', '초구는 그 발을 꾸민다. 수레를 버리고 걸어간다.', '象曰：「舍車而徒」、義弗乘也。'),(130, 22, 2, '六二 賁其須。', '육이는 그 수염을 꾸민다.', '象曰：「賁其須」、與上興也。'),(131, 22, 3, '九三 賁如濡如，永貞吉。', '구삼. 꾸밈이 있고 윤택함이 있으니, 길이 곧게 지키면 길하다.', '象曰：「永貞」之「吉」、終莫之陵也。'),(132, 22, 4, '六四 賁如皤如，白馬翰如，匪寇，婚媾。', '육사는 꾸밈이 있는 듯하나 희게 되고, 흰 말이 날아오르는 듯하니, 도적이 아니라 혼인하는 것이다.', '象曰：「六四」、當位疑也，「匪寇婚媾」、終無尤也。'),(133, 22, 5, '六五 賁于丘園，束帛戔戔，吝終吉。', '육오는 언덕과 동산에서 꾸밈을 받으니, 묶은 비단이 잘게 나뉘어 있다. 부끄러우나 마침내 길하다.', '象曰：「六五」之「吉」、有喜也。'),(134, 22, 6, '上九 白賁，無咎。', '상구, 흰 꾸밈이니 허물이 없다.', '象曰：「白賁無咎」、上得志也。'),(135, 23, 1, '初六 剝牀以足，蔑貞凶。', '초육은 침상을 발부터 벗긴다. 곧음을 없애니 흉하다.', '象曰：「剝牀以足」、以滅下也。'),(136, 23, 2, '六二 剝牀以辨，蔑貞凶。', '육이는 평상을 벗겨 변에 이르니, 바름을 멸시하면 흉하다.', '象曰：「剝牀以辨」、未有與也。'),(137, 23, 3, '六三 剝之無咎。', '육삼은 벗겨냄에서 벗어나니 허물이 없다.', '象曰：「剝之無咎」、失上下也。'),(138, 23, 4, '六四 剝牀以膚，凶。', '육사는 평상을 벗겨 살갗에 이르니, 흉하다.', '象曰：「剝牀以膚」、切近災也。'),(139, 23, 5, '六五 貫魚以宮人寵，無不利。', '육오. 물고기를 꿰듯 하여 궁인의 총애를 얻으니, 이롭지 않음이 없다.', '象曰：「以宮人寵」、終無尤也。'),(140, 23, 6, '上九 碩果不食，君子得輿，小人剝廬。', '상구는 큰 열매를 먹지 않으니, 군자는 수레를 얻고 소인은 집을 벗긴다.', '象曰：「君子得輿」、民所載也，「小人剝廬」、終不可用也。'),(141, 24, 1, '初九 不遠復，無祗悔，元吉。', '초구는 멀리 가지 않아 돌아오니, 뉘우침에 이르지 않아 크게 길하다.', '象曰：「不遠」之「復」、以修身也。'),(142, 24, 2, '六二 休復，吉。', '육이는 아름답게 돌아오니 길하다.', '象曰：「休復」之「吉」、以下仁也。'),(143, 24, 3, '六三 頻復，厲、無咎。', '육삼은 자주 돌아오니, 위태로우나 허물이 없다.', '象曰：「頻復」之「厲」、義「無咎」也。'),(144, 24, 4, '六四 中行獨復。', '육사는 무리 가운데 행하면서 홀로 돌아온다.', '象曰：「中行獨復」、以從道也。'),(145, 24, 5, '六五 敦復，無悔。', '육오. 돈독하게 돌아오니, 뉘우침이 없다.', '象曰：「敦復無悔」、中以自考也。'),(146, 24, 6, '上六 迷復，凶，有災眚。用行師，終有大敗，以其國君凶，至于十年不克征。', '상육. 미혹하여 돌아오니, 흉하고, 재앙과 허물이 있다. 군대를 일으키면 마침내 크게 패하고, 그 나라의 임금에게 흉하니, 십 년에 이르도록 정벌하지 못한다.', '象曰：「迷復」之「凶」、反君道也。'),(147, 25, 1, '初九 無妄，往吉。', '초구는 무망하니, 나아가면 길하다.', '象曰：「無妄」之「往」、得志也。'),(148, 25, 2, '六二 不耕穫；不菑畬；則利有攸往。', '육이는 밭을 갈지 않고 거두며, 처음 개간하지 않고 묵은 밭을 얻으니, 나아갈 바가 있으면 이롭다.', '象曰：「不耕穫」、未富也。'),(149, 25, 3, '六三 無妄之災，或繫之牛，行人之得，邑人之災。', '육삼. 무망의 재앙이니, 혹 소를 매어두었는데 가는 사람이 얻으니 마을 사람의 재앙이다.', '象曰：「行人得」牛、「邑人災」也。'),(150, 25, 4, '九四 可貞，無咎。', '구사. 곧게 지킬 만하니, 허물이 없다.', '象曰：「可貞無咎」、固有之也。'),(151, 25, 5, '九五 無妄之疾，勿藥有喜。', '구오. 무망의 병이니, 약을 쓰지 말면 기쁨이 있다.', '象曰：「無妄」之「藥」、不可試也。'),(152, 25, 6, '上九 無妄，行有眚，無攸利。', '상구는 무망함에, 행하면 재앙이 있고 이로울 바가 없다.', '象曰：「無妄」之「行」、窮之災也。'),(153, 26, 1, '初九 有厲，利已。', '초구는 위태로움이 있으니, 그침이 이롭다.', '象曰：「有厲利已」、不犯災也。'),(154, 26, 2, '九二 輿說輹。', '구이는 수레가 바퀴 덮개를 벗긴다.', '象曰：「輿說輹」、中無尤也。'),(155, 26, 3, '九三 良馬逐，利艱貞，曰閑輿衛，利有攸往。', '구삼. 좋은 말이 달려가니, 어렵게 곧게 지키면 이롭다. 날마다 수레와 방위를 익히면 나아갈 바가 있음이 이롭다.', '象曰：「利有攸往」、上合志也。'),(156, 26, 4, '六四 童牛之牿，元吉。', '육사. 어린 소에게 고를 씌우니, 크게 길하다.', '象曰：「六四元吉」、有喜也。'),(157, 26, 5, '六五 豶豕之牙，吉。', '육오. 거세한 돼지의 어금니이니, 길하다.', '象曰：「六五」之「吉」、有慶也。'),(158, 26, 6, '上九 何天之衢，亨。', '상구. 하늘의 네거리를 짊어지니, 형통하다.', '象曰：「何天之衢」、道大行也。'),(159, 27, 1, '初九 舍爾靈龜，觀我朶頤，凶。', '초구는 너의 신령한 거북을 버리고 나의 턱이 움직이는 것을 보니 흉하다.', '象曰：「觀我朶頤」、亦不足貴也。'),(160, 27, 2, '六二 顚頤，拂經于丘，頤、征凶。', '육이는 이(頤)를 뒤집어서 경(經)을 어기고 언덕에서 이(頤)를 구하니, 나아가면 흉하다.', '象曰：「六二征凶」、行失類也。'),(161, 27, 3, '六三 拂頤貞、凶，十年勿用，無攸利。', '육삼은 이(頤)를 거스르되 곧게 지키면 흉하니, 십 년 동안 쓰지 말라. 이로운 바가 없다.', '象曰：「十年勿用」、道大悖也。'),(162, 27, 4, '六四 顚頤，吉。虎視耽耽，其欲逐逐，無咎。', '육사는 거꾸로 기름이니, 길하다. 호랑이가 보듯 눈빛이 탐탐하고, 그 욕구가 축축하면, 허물이 없다.', '象曰：「顚頤」之「吉」、上施光也。'),(163, 27, 5, '六五 拂經，居貞、吉，不可涉大川。', '육오는 경(經)을 거스르나, 곧게 지키면 길하다. 큰 내를 건너서는 안 된다.', '象曰：「居貞」之「吉」、順以從上也。'),(164, 27, 6, '上九 由頤，厲、吉。利涉大川。', '상구는 말미암아 기름이니, 위태로우나 길하다. 큰 내를 건너는 것이 이롭다.', '象曰：「由頤厲吉」、大有慶也。'),(165, 28, 1, '初六 藉用白茅，無咎。', '초육은 흰 띠풀을 깔아 쓰니, 허물이 없다.', '象曰：「藉用白茅」、柔在下也。'),(166, 28, 2, '九二 枯楊生稊，老夫得其女妻，無不利。', '구이는 마른 버드나무가 뿌리를 내고, 늙은 남편이 젊은 아내를 얻으니, 이롭지 않음이 없다.', '象曰：「老夫女妻」、過以相與也。'),(167, 28, 3, '九三 棟橈，凶。', '구삼, 마룻대가 휘어지니 흉하다.', '象曰：「棟橈」之「凶」、不可以有輔也。'),(168, 28, 4, '九四 棟隆、吉。有它、吝。', '구사. 동이 융기하니 길하다. 다른 것이 있으면 부끄럽다.', '象曰：「棟隆」之「吉」、不橈乎下也。'),(169, 28, 5, '九五 枯楊生華，老婦得其士夫，無咎無譽。', '구오. 마른 버드나무가 꽃을 피우고, 늙은 부인이 그 젊은 남편을 얻으니, 허물도 없고 명예도 없다.', '象曰：「枯楊生華」、何可久也，「老婦士夫」、亦可醜也。'),(170, 28, 6, '上六 過涉滅頂，凶。無咎。', '상육. 지나치게 건너서 정수리까지 잠기니, 흉하다. 허물은 없다.', '象曰：「過涉」之「凶」、不可咎也。'),(171, 29, 1, '初六 習坎，入于坎窞，凶。', '초육은 거듭된 구덩이에서 구덩이의 깊은 곳으로 들어가니, 흉하다.', '象曰：「習坎入坎」、失道「凶」也。'),(172, 29, 2, '九二 坎有險，求小得。', '구이는 감에 험함이 있으나, 구하여 조금 얻는다.', '象曰：「求小得」、未出中也。'),(173, 29, 3, '六三 來之坎坎，險且枕，入于坎窞，勿用。', '육삼. 오고 가도 거듭 구덩이요, 험하고 또 베개하니, 구덩이 구렁에 들어가는지라, 쓰지 말라.', '象曰：「來之坎坎」、終無功也。'),(174, 29, 4, '六四 樽酒、簋貳、用缶，納約自牖，終無咎。', '육사. 한 동이의 술과 두 그릇의 음식을 질그릇으로 사용하여, 약속을 창으로부터 들여놓으면, 마침내 허물이 없다.', '象曰：「樽酒簋貳」、剛柔際也。'),(175, 29, 5, '九五 坎不盈，祗旣平，無咎。', '구오. 감이 차지 않고, 다만 이미 평평하니, 허물이 없다.', '象曰：「坎不盈」、中未大也。'),(176, 29, 6, '上六 係用徽纆，寘于叢棘，三歲不得，凶。', '상육. 굵은 밧줄과 검은 밧줄로 묶어 가시덤불 속에 두니, 삼 년이 되도록 벗어나지 못하면 흉하다.', '象曰：「上六」失道、「凶」「三歲」也。'),(177, 30, 1, '初九 履錯然敬之，無咎。', '초구는 밟음이 어긋나지만 이를 공경하면 허물이 없다.', '象曰：「履錯」之「敬」、以辟咎也。'),(178, 30, 2, '六二 黃離，元吉。', '육이는 누런 빛의 리이니, 크게 길하다.', '象曰：「黃離元吉」、得中道也。'),(179, 30, 3, '九三 日昃之離，不鼓缶而歌，則大耋之嗟，凶。', '구삼은 해가 기울 때의 밝음이니, 질그릇을 두드리며 노래하지 않으면 크게 늙음을 탄식하게 되어 흉하다.', '象曰：「日昃之離」、何可久也？'),(180, 30, 4, '九四 突如、其來如，焚如，死如，棄如。', '구사. 갑자기 그 옴이 이와 같고, 불타는 것이 이와 같고, 죽음이 이와 같고, 버려짐이 이와 같다.', '象曰：「突如其來如」、無所容也。'),(181, 30, 5, '六五 出涕沱若，戚嗟若，吉。', '육오. 눈물이 흘러내리는 듯하고, 슬퍼하며 탄식하는 듯하면, 길하다.', '象曰：「六五」之「吉」、離王公也。'),(182, 30, 6, '上九 王用出征，有嘉折首，獲匪其醜，無咎。', '상구. 왕이 출정함에 쓰니, 아름다움이 있어 머리를 꺾고, 그 무리가 아닌 것을 사로잡으니, 허물이 없다.', '象曰：「王用出征」、以正邦也。'),(183, 31, 1, '初六 咸其拇。', '초육은 그 엄지발가락을 감응시킨다.', '象曰：「咸其拇」、志在外也。'),(184, 31, 2, '六二 咸其腓，凶。居吉。', '육이는 그 장딴지를 감응시키니 흉하다. 거처하면 길하다.', '象曰：雖「凶居吉」、順不害也。'),(185, 31, 3, '九三 咸其股，執其隨，往吝。', '구삼은 그 넓적다리를 감응시키니, 그 따름을 잡아 나아가면 부끄러움이 있다.', '象曰：「咸其股」、亦不處也，志在「隨」人、所「執」下也。'),(186, 31, 4, '九四 貞吉。悔亡。憧憧往來，朋從爾思。', '구사. 곧게 지키면 길하고 뉘우침이 사라진다. 왕래함이 분주하면 벗이 네 생각을 따른다.', '象曰：「貞吉悔亡」、未感害也，「憧憧往來」、未光大也。'),(187, 31, 5, '九五 咸其脢，無悔。', '구오. 그 등을 감응시키니, 뉘우침이 없다.', '象曰：「咸其脢」、志末也。'),(188, 31, 6, '上六 咸其輔頰舌。', '상육. 그 턱과 뺨과 혀를 감응시킨다.', '象曰：「咸其輔頰舌」、滕口說也。'),(189, 32, 1, '初六 浚恒，貞凶，無攸利。', '초육은 항구함을 깊이 구하니, 곧게 지켜도 흉하고, 이로운 바가 없다.', '象曰：「浚恒」之「凶」、始求深也。'),(190, 32, 2, '九二 悔亡。', '구이는 뉘우침이 사라진다.', '象曰：「九二悔亡」、能久中也。'),(191, 32, 3, '九三 不恒其德，或承之羞，貞吝。', '구삼. 그 덕을 항상되게 하지 못하면, 혹 수치를 받게 되니, 곧게 지켜도 부끄럽다.', '象曰：「不恒其德」、無所容也。'),(192, 32, 4, '九四 田無禽。', '구사. 사냥하되 짐승이 없다.', '象曰：久非其位，安得「禽」也。'),(193, 32, 5, '六五 恒其德、貞，婦人吉，夫子凶。', '육오. 그 덕을 항구히 하되 곧게 지키면, 부인은 길하나 부자는 흉하다.', '象曰：「婦人貞吉」、從一而終也。「夫子」制義、從婦「凶」也。'),(194, 32, 6, '上六 振恒，凶。', '상육, 항상함을 떨치니 흉하다.', '象曰：「振恒」在上、大無功也。'),(195, 33, 1, '初六 遯尾、厲，勿用有攸往。', '초육은 둔의 꼬리이니 위태로우므로, 나아가는 바가 있는 데 쓰지 말라.', '象曰：「遯尾」之「厲」、不往何災也？'),(196, 33, 2, '六二 執之用黃牛之革，莫之勝、說。', '육이는 그것을 잡되 누런 소의 가죽으로 하니, 그것을 벗기거나 풀 수 없다.', '象曰：「執用黃牛」、固志也。'),(197, 33, 3, '九三 係遯，有疾厲，畜臣妾吉。', '구삼은 묶여서 물러남이니, 병이 있어 위태롭다. 신첩을 기르면 길하다.', '象曰：「係遯」之「厲」、有疾憊也，「畜臣妾吉」、不可大事也。'),(198, 33, 4, '九四 好遯，君子吉，小人否。', '구사. 좋아하는 것이 있으나 물러남이니, 군자는 길하고 소인은 불길하다.', '象曰：「君子好遯、小人否」也。'),(199, 33, 5, '九五 嘉遯，貞吉。', '구오, 아름다운 물러남이니, 곧게 지키면 길하다.', '象曰：「嘉遯貞吉」、以正志也。'),(200, 33, 6, '上九 肥遯，無不利。', '상구, 살찌게 물러남이니 이롭지 않음이 없다.', '象曰：「肥遯無不利」、無所疑也。'),(201, 34, 1, '初九 壯于趾，征凶有孚。', '초구는 발가락에서 장성함이니, 나아가면 흉하리라는 것이 미더우니라.', '象曰：「壯于趾」、其「孚」窮也。'),(202, 34, 2, '九二 貞吉。', '구이는 곧게 지키면 길하다.', '象曰：「九二貞吉」、以中也。'),(203, 34, 3, '九三 小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。', '구삼. 소인은 강함을 쓰고, 군자는 무(罔)를 쓰니, 곧게 지켜도 위태롭다. 숫양이 울타리를 들이받아 그 뿔이 걸린다.', '象曰：「小人用壯、君子用罔」也。'),(204, 34, 4, '九四 貞吉，悔亡。藩決不羸，壯于大輿之輹。', '구사. 곧게 지키면 길하고, 뉘우침이 사라진다. 울타리가 터져도 얽매이지 않으니, 큰 수레의 바퀴통에 장함이 있다.', '象曰：「藩決不羸」、尙往也。'),(205, 34, 5, '六五 喪羊于易，無悔。', '육오. 양을 평이한 곳에서 잃으니, 뉘우침이 없다.', '象曰：「喪羊于易」、位不當也。'),(206, 34, 6, '上六 羝羊觸藩，不能退，不能遂，無攸利，艱則吉。', '상육. 숫양이 울타리를 들이받아 물러날 수도 없고 나아갈 수도 없으니, 이로울 바가 없다. 어려움을 알면 길하다.', '象曰：「不能退、不能遂」、不詳也，「艱則吉」、咎不長也。'),(207, 35, 1, '初六 晉如摧如，貞吉。罔孚，裕無咎。', '초육. 나아가는 듯 꺾이는 듯하니, 곧게 지키면 길하다. 미더움이 없으면, 너그러우면 허물이 없다.', '象曰：「晉如摧如」、獨行正也，「裕無咎」、未受命也。'),(208, 35, 2, '六二 晉如，愁如，貞吉。受玆介福于其王母。', '육이는 나아가려 하나 근심스럽다. 곧게 지키면 길하다. 이에 큰 복을 그 왕모로부터 받는다.', '象曰：「受玆介福」、以中正也。'),(209, 35, 3, '六三 眾允，悔亡。', '육삼은 뭇 사람이 따르니, 뉘우침이 없어진다.', '象曰：「眾允」之、志上行也。'),(210, 35, 4, '九四 晉如鼫鼠，貞厲。', '구사는 나아감이 석서와 같으니, 곧게 지키면 위태롭다.', '象曰：「鼫鼠貞厲」、位不當也。'),(211, 35, 5, '六五 悔亡，失得勿恤。往吉，無不利。', '육오. 뉘우침이 없어진다. 잃고 얻음을 근심하지 말라. 나아가면 길하니, 이롭지 않음이 없다.', '象曰：「失得勿恤」、往有慶也。'),(212, 35, 6, '上九 晉其角，維用伐邑，厲吉，無咎，貞吝。', '상구는 그 뿔로 나아가니, 오직 읍을 치는 데에만 쓴다. 위태로우나 길하고 허물이 없으나, 곧게 지키면 부끄럽다.', '象曰：「維用伐邑」、道未光也。'),(213, 36, 1, '初九 明夷于飛，垂其翼。君子于行，三日不食。有攸往，主人有言。', '초구는 밝음이 상하여 날아오르되 그 날개를 드리운다. 군자가 행할 때 삼 일 동안 먹지 못한다. 가는 바가 있으면 주인이 말이 있다.', '象曰：「君子于行」、義「不食」也。'),(214, 36, 2, '六二 明夷、夷于左股，用拯馬、壯吉。', '육이는 명이(明夷)니, 왼쪽 넓적다리를 다쳤으나, 건장한 말을 써서 구하면 길하다.', '象曰：「六二」之「吉」、順以則也。'),(215, 36, 3, '九三 明夷于南狩，得其大首，不可疾貞。', '구삼은 명이가 남쪽으로 사냥함에 이르러 그 큰 머리를 얻으나, 급히 바르게 할 수 없다.', '象曰：「南狩」之志、乃大得也。'),(216, 36, 4, '六四 入于左腹，獲明夷之心于出門庭。', '육사는 왼쪽 배로 들어가서, 명이의 마음을 얻어 문정으로 나간다.', '象曰：「入于左腹」、獲心意也。'),(217, 36, 5, '六五 箕子之明夷，利貞。', '육오, 기자의 명이이니, 곧게 지키면 이롭다.', '象曰：「箕子」之「貞」、「明」不可息也。'),(218, 36, 6, '上六 不明、晦。初登于天，後入于地。', '상육. 밝지 못하여 어둡다. 처음에는 하늘에 올랐으나, 뒤에는 땅으로 들어간다.', '象曰：「初登于天」、照四國也，「後入于地」、失則也。'),(219, 37, 1, '初九 閑有家，悔亡。', '초구는 집안을 막아 다스리니, 뉘우침이 없어진다.', '象曰：「閑有家」、志未變也。'),(220, 37, 2, '六二 無攸遂，在中饋，貞吉。', '육이는 나아가 이룰 바가 없고, 안에서 음식을 맡아 다스리니, 곧게 지키면 길하다.', '象曰：「六二」之「吉」、順以巽也。'),(221, 37, 3, '九三 家人嗃嗃，悔厲，吉；婦子嘻嘻，終吝。', '구삼은 집안사람들이 엄하니, 뉘우치고 위태로우나 길하다. 부인과 자식이 희희낙락하면 마침내 부끄럽다.', '象曰：「家人嗃嗃」、未失也，「婦子嘻嘻」、失家節也。'),(222, 37, 4, '六四 富家，大吉。', '육사는 집을 부유하게 하니, 크게 길하다.', '象曰：「富家大吉」、順在位也。'),(223, 37, 5, '九五 王假有家，勿恤，吉。', '구오. 왕이 집안을 이루니, 근심하지 말라, 길하다.', '象曰：「王假有家」、交相愛也。'),(224, 37, 6, '上九 有孚威如，終吉。', '상구. 미더움이 있어 위엄스러우니, 마침내 길하다.', '象曰：「威如」之「吉」、反身之謂也。'),(225, 38, 1, '初九 悔亡。喪馬，勿逐自復。見惡人無咎。', '초구는 뉘우침이 사라진다. 말을 잃었으나 쫓지 말라, 스스로 돌아온다. 악한 사람을 만나면 허물이 없다.', '象曰：「見惡人」、以辟「咎」也。'),(226, 38, 2, '九二 遇主于巷，無咎。', '구이는 주인을 골목에서 만나니, 허물이 없다.', '象曰：「遇主于巷」、未失道也。'),(227, 38, 3, '六三 見輿曳，其牛掣，其人天且劓，無初有終。', '육삼은 수레가 끌려가는 것을 보고, 그 소가 제지당하며, 그 사람이 이마에 묵형을 당하고 또 코가 베어지나, 처음은 없으나 마침내는 있다.', '象曰：「見輿曳」、位不當也，「無初有終」、遇剛也。'),(228, 38, 4, '九四 睽孤，遇元夫，交孚，厲無咎。', '구사는 어긋남 속에서 외로우나, 으뜸 지아비를 만나 사귐에 미더우면, 위태로우나 허물이 없다.', '象曰：「交孚無咎」、志行也。'),(229, 38, 5, '六五 悔亡。厥宗噬膚，往何咎？', '육오. 뉘우침이 사라진다. 그 종족이 살을 물어뜯으니, 나아가면 무슨 허물이 있겠는가?', '象曰：「厥宗噬膚」、「往」有慶也。'),(230, 38, 6, '上九 睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇，婚媾。往遇雨，則吉。', '상구는 외로이 어긋나 있으니, 진흙을 등에 진 돼지를 보고, 귀신을 가득 실은 수레를 보며, 먼저 활을 당기다가 뒤에 활을 풀어놓는다. 도적이 아니라 혼인하는 이이다. 나아가 비를 만나면 곧 길하다.', '象曰：「遇雨」之「吉」、群疑亡也。'),(231, 39, 1, '初六 往蹇來譽。', '초육은 나아가면 어려움이고 돌아오면 명예로움이다.', '象曰：「往蹇來譽」、宜待也。'),(232, 39, 2, '六二 王臣蹇蹇，匪躬之故。', '육이는 왕의 신하로서 간난하고 또 간난하니, 몸을 위한 까닭이 아니다.', '象曰：「王臣蹇蹇」、終無尤也。'),(233, 39, 3, '九三 往蹇來反。', '구삼은 나아가면 곤란하고, 돌아오면 돌아온다.', '象曰：「往蹇來反」、內喜之也。'),(234, 39, 4, '六四 往蹇來連。', '육사는 나아가면 준애하고 돌아오면 연합한다.', '象曰：「往蹇來連」、當位實也。'),(235, 39, 5, '九五 大蹇，朋來。', '구오, 큰 어려움이나 벗이 온다.', '象曰：「大蹇朋來」、以中節也。'),(236, 39, 6, '上六 往蹇，來碩，吉，利見大人。', '상육. 나아가면 곤란하고, 돌아오면 크니, 길하다. 대인을 만나면 이롭다.', '象曰：「往蹇來碩」、志在內也，「利見大人」、以從貴也。'),(237, 40, 1, '初六 無咎。', '초육은 허물이 없다.', '象曰：剛柔之際，義「無咎」也。'),(238, 40, 2, '九二 田獲三狐，得黃矢，貞吉。', '구이는 사냥하여 세 마리의 여우를 잡고, 누런 화살을 얻으니, 곧게 지키면 길하다.', '象曰：「九二」「貞吉」、得中道也。'),(239, 40, 3, '六三 負且乘，致寇至，貞吝。', '육삼은 짐을 지고 또 수레를 탄다. 도적이 이르게 한다. 곧게 지켜도 부끄럽다.', '象曰：「負且乘」、亦可醜也。自我致戎，又誰咎也？'),(240, 40, 4, '九四 解而拇，朋至斯孚。', '구사는 엄지발가락을 풀어내니, 벗이 이르러 미더움이 있다.', '象曰：「解而拇」、未當位也。'),(241, 40, 5, '六五 君子維有解，吉，有孚于小人。', '육오. 군자가 오직 풀어냄이 있으면 길하니, 소인에게서 미더움이 있다.', '象曰：「君子有解」、「小人」退也。'),(242, 40, 6, '上六 公用射隼于高墉之上，獲之，無不利。', '상육. 공이 높은 담 위에 있는 매를 쏘아 잡으니, 이롭지 않음이 없다.', '象曰：「公用射隼」、以解悖也。'),(243, 41, 1, '初九 已事遄往，無咎。酌損之。', '초구는 일을 마치고 빨리 가면 허물이 없다. 헤아려서 덜어낸다.', '象曰：「已事遄往」，尙合志也。'),(244, 41, 2, '九二 利貞。征凶，弗損，益之。', '구이는 곧게 지키면 이롭다. 나아가면 흉하니, 스스로를 손상하지 않으면 위를 더하게 된다.', '象曰：「九二利貞」，中以爲志也。'),(245, 41, 3, '六三 三人行則損一人，一人行則得其友。', '육삼. 세 사람이 가면 한 사람을 덜고, 한 사람이 가면 그 벗을 얻는다.', '象曰：「一人行」，「三」則疑也。'),(246, 41, 4, '六四 損其疾，使遄有喜，無咎。', '육사는 그 병을 덜어내니, 빠르게 하면 기쁨이 있고 허물이 없다.', '象曰：「損其疾」，亦可「喜」也。'),(247, 41, 5, '六五 或益之十朋之龜，弗克違，元吉。', '육오. 혹 이를 보태어 십붕의 거북이라도 어기지 못하니, 크게 길하다.', '象曰：「六五」「元吉」，自上祐也。'),(248, 41, 6, '上九 弗損，益之，無咎，貞吉，利有攸往，得臣無家。', '상구. 덜어내지 않고 보태주면 허물이 없고, 곧게 지키면 길하며, 나아갈 바가 있으면 이롭다. 신하를 얻되 집안이 없다.', '象曰：「弗損、益之」，大得志也。'),(249, 42, 1, '初九 利用爲大作，元吉，無咎。', '초구는 큰 일을 하는 데 쓰면 이롭다. 크게 길하면 허물이 없다.', '象曰：「元吉無咎」、下不厚事也。'),(250, 42, 2, '六二 或益之，十朋之龜弗克違。永貞吉。王用享于帝，吉。', '육이. 혹 이를 더해주니, 열 벗의 거북도 어기지 못한다. 영원히 곧게 지키면 길하다. 왕이 이로써 상제에게 제사 지내면 길하다.', '象曰：「或益之」、自外來也。'),(251, 42, 3, '六三 益之，用凶事無咎。有孚，中行。告公用圭。', '육삼은 이롭게 함을 흉한 일에 쓰면 허물이 없다. 미더움이 있어 치우치지 않게 행하면, 공에게 알려 규를 쓴다.', '象曰：「益用凶事」、固有之也。'),(252, 42, 4, '六四 中行告公，從，利用爲依遷國。', '육사. 치우치지 않게 행하여 공에게 알려주면 따르니, 의지가 되어 나라를 옮기는 데 쓰면 이롭다.', '象曰：「告公從」、以益志也。'),(253, 42, 5, '九五 有孚惠心，勿問，元吉。有孚惠我德。', '구오. 미더움이 있어 마음을 은혜롭게 하니, 묻지 않아도 크게 길하다. 미더움이 있어 우리의 덕을 은혜롭게 한다.', '象曰：「有孚惠心」、「勿問」之矣，「惠我德」、大得志也。'),(254, 42, 6, '上九 莫益之，或擊之，立心勿恒，凶。', '상구. 더해주는 이가 없고, 혹 치니, 마음을 세움에 항상함이 없으면 흉하다.', '象曰：「莫益之」、偏辭也，「或擊之」、自外來也。'),(255, 43, 1, '初九 壯于前趾，往不勝，爲咎。', '초구는 앞 발가락에서 굳세니, 나아가도 이기지 못하면 허물이 된다.', '象曰：「不勝」而「往」、「咎」也。'),(256, 43, 2, '九二 惕號，莫夜有戎，勿恤。', '구이. 두려워하며 경계하니, 밤중에 적병이 있어도 근심하지 말라.', '象曰：「有戎勿恤」、得中道也。'),(257, 43, 3, '九三 壯于頄，有凶。獨行遇雨，君子夬夬、若濡，有慍無咎。', '구삼. 광대뼈에서 세니 흉함이 있다. 홀로 가다가 비를 만나면, 군자는 결단하고 또 결단하여 비록 젖더라도 분한 마음이 있으면 허물이 없다.', '象曰：「君子夬夬」、終「無咎」也。'),(258, 43, 4, '九四 臀無膚，其行次且。牽羊悔亡。聞言不信。', '구사. 볼기에 살이 없어 그 행함이 머뭇거린다. 양을 끌면 뉘우침이 없어지나, 말을 들어도 믿지 않는다.', '象曰：「其行次且」、位不當也，「聞言不信」、聰不明也。'),(259, 43, 5, '九五 莧陸夬夬，中行無咎。', '구오. 현륙을 결단하고 또 결단하니, 중행하면 허물이 없다.', '象曰：「中行無咎」、中未光也。'),(260, 43, 6, '上六 無號，終有凶。', '상육. 부르짖지 못하니, 마침내 흉함이 있다.', '象曰：「無號」之「凶」、終不可長也。'),(261, 44, 1, '初六 繫于金柅，貞吉。有攸往，見凶，羸豕孚蹢躅。', '초육. 쇠로 된 바퀴멈춤쇠에 묶인다. 곧게 지키면 길하다. 나아갈 바가 있으면 흉함을 보게 된다. 여윈 돼지가 미더이 뛰놀다.', '象曰：「繫于金柅」、柔道牽也。'),(262, 44, 2, '九二 包有魚，無咎，不利賓。', '구이. 포(包) 안에 물고기가 있으니, 허물이 없다. 손님에게는 이롭지 않다.', '象曰：「包有魚」、義不及「賓」也。'),(263, 44, 3, '九三 臀無膚，其行次且，厲，無大咎。', '구삼. 볼기에 살이 없어 그 걸음이 더디고 머뭇거린다. 위태로우나 큰 허물은 없다.', '象曰：「其行次且」、行未牽也。'),(264, 44, 4, '九四 包無魚，起凶。', '구사. 포에 물고기가 없으니, 흉함이 일어난다.', '象曰：「無魚」之「凶」、遠民也。'),(265, 44, 5, '九五 以杞包瓜，含章，有隕自天。', '구오. 기나무로 오이를 싸고, 아름다움을 품으니, 하늘로부터 내려옴이 있다.', '象曰：「九五」「含章」、中正也，「有隕自天」、志不舍命也。'),(266, 44, 6, '上九 姤其角，吝，無咎。', '상구는 그 뿔로 만난다. 부끄러우나 허물은 없다.', '象曰：「姤其角」、上窮「吝」也。'),(267, 45, 1, '初六 有孚不終，乃亂乃萃，若號一握爲笑，勿恤，往無咎。', '초육. 미더움이 있으나 끝까지 가지 못하니, 이에 어지럽고 이에 모인다. 만약 부르짖으면 한 무리가 웃음거리가 되리니, 근심하지 말고 나아가면 허물이 없다.', '象曰：「乃亂乃萃」、其志亂也。'),(268, 45, 2, '六二 引吉，無咎，孚乃利用禴。', '육이는 끌어당기면 길하고 허물이 없으며, 미더움이 있으면 약제를 쓰는 것이 이롭다.', '象曰：「引吉無咎」、中未變也。'),(269, 45, 3, '六三 萃如嗟如，無攸利，往無咎，小吝。', '육삼은 모이려 하나 탄식하니, 이로울 바가 없다. 나아가면 허물이 없으나, 조금 부끄럽다.', '象曰：「往無咎」、上巽也。'),(270, 45, 4, '九四 大吉無咎。', '구사. 크게 길하면 허물이 없다.', '象曰：「大吉無咎」、位不當也。'),(271, 45, 5, '九五 萃有位，無咎。匪孚，元、永貞悔亡。', '구오. 모임에 자리가 있으니 허물이 없다. 미더움이 아니면 으뜸되고 영원히 곧게 지켜 뉘우침이 사라진다.', '象曰：「萃有位」、志未光也。'),(272, 45, 6, '上六 齎咨涕洟，無咎。', '상육. 탄식하며 눈물과 콧물을 흘리나, 허물이 없다.', '象曰：「齎咨涕洟」、未安上也。'),(273, 46, 1, '初六 允升，大吉。', '초육은 믿고 올라가니, 크게 길하다.', '象曰：「允升大吉」、上合志也。'),(274, 46, 2, '九二 孚乃利用禴，無咎。', '구이. 미더움이 있으면 약제를 쓰는 것이 이로우니, 허물이 없다.', '象曰：「九二」之「孚」、有喜也。'),(275, 46, 3, '九三 升虛邑。', '구삼은 빈 고을로 올라간다.', '象曰：「升虛邑」、無所疑也。'),(276, 46, 4, '六四 王用亨于岐山，吉，無咎。', '육사. 왕이 기산에서 형통함을 이루니, 길하고 허물이 없다.', '象曰：「王用亨于岐山」、順事也。'),(277, 46, 5, '六五 貞吉，升階。', '육오. 곧게 지키면 길하니, 계단을 올라간다.', '象曰：「貞吉升階」、大得志也。'),(278, 46, 6, '上六 冥升，利于不息之貞。', '상육, 어둡게 오르니, 쉬지 않는 곧음에 이롭다.', '象曰：「冥升」在上、消不富也。'),(279, 47, 1, '初六 臀困于株木，入于幽谷，三歲不覿。', '초육은 볼기가 그루터기에 곤궁하고, 깊은 골짜기에 들어가니, 삼 년이 되어도 만나지 못한다.', '象曰：「入于幽谷」，幽、不明也。'),(280, 47, 2, '九二 困于酒食，朱紱方來。利用亨祀。征凶無咎。', '구이는 술과 음식에 곤궁하나, 붉은 무릎가리개가 바야흐로 온다. 제사 지내는 데 쓰면 이롭다. 나아가면 흉하나 허물은 없다.', '象曰：「困于酒食」、中有慶也。'),(281, 47, 3, '六三 困于石，據于蒺藜，入于其宮，不見其妻，凶。', '육삼은 돌에 곤궁하고, 가시덤불을 디디며, 그 집에 들어가도 그 아내를 보지 못하니, 흉하다.', '象曰：「據于蒺藜」、乘剛也，「入于其宮不見其妻」、不祥也。'),(282, 47, 4, '九四 來徐徐，困于金車，吝，有終。', '구사. 오는 것이 더디고 더디니, 쇠수레에 막혀 곤궁하다. 부끄러우나 마침내 이룸이 있다.', '象曰：「來徐徐」、志在下也。雖不當位，有與也。'),(283, 47, 5, '九五 劓刖，困于赤紱，乃徐有說，利用祭祀。', '구오. 코를 베이고 발을 자르니, 붉은 끈에 곤궁하다가, 이에 서서히 벗어남이 있다. 제사 지내는 데 쓰면 이롭다.', '象曰：「劓刖」、志未得也，「乃徐有說」、以中直也，「利用祭祀」、受福也。'),(284, 47, 6, '上六 困于葛藟，于臲卼，曰動悔有悔，征吉。', "상육은 갈등(葛藟)에 곤궁하고 위태롭게 흔들림에 곤궁하다. 스스로 말하기를 ''움직이면 뉘우침이 있으니 뉘우쳐야 한다''고 하면, 나아가면 길하다.", '象曰：「困于葛藟」、未當也，「動悔有悔」、「吉」行也。'),(285, 48, 1, '初六 井泥不食。舊井無禽。', '초육은 우물이 진흙투성이라 먹지 못하고, 낡은 우물에는 새가 없다.', '象曰：「井泥不食」、下也，「舊井無禽」、時舍也。'),(286, 48, 2, '九二 井谷射鮒，甕敝漏。', '구이는 우물 골짜기가 붕어에게 쏟아지고, 독이 깨져 샌다.', '象曰：「井谷射鮒」、無與也。'),(287, 48, 3, '九三 井渫不食，爲我心惻。可用汲，王明，竝受其福。', '구삼. 우물을 깨끗이 하였으나 먹지 않으니, 나의 마음이 슬프다. 길어 쓸 수 있거늘, 왕이 밝으면 함께 그 복을 받으리라.', '象曰：「井渫不食」、行「惻」也，求「王明」、「受福」也。'),(288, 48, 4, '六四 井甃，無咎。', '육사는 우물을 벽돌로 쌓으니, 허물이 없다.', '象曰：「井甃無咎」、修井也。'),(289, 48, 5, '九五 井冽寒泉，食。', '구오. 우물이 맑고 차가운 샘이니, 먹는다.', '象曰：「寒泉」之「食」、中正也。'),(290, 48, 6, '上六 井收勿幕，有孚元吉。', '상육, 우물을 거두되 덮지 말라. 미더움이 있으면 크게 길하다.', '象曰：「元吉」在「上」、大成也。'),(291, 49, 1, '初九 鞏用黃牛之革。', '초구는 누런 소의 가죽으로 굳게 묶는다.', '象曰：「鞏用黃牛」、不可以有爲也。'),(292, 49, 2, '六二 已日乃革之，征吉，無咎。', '육이는 이미 날에 이르러 이를 고치니, 나아가면 길하고 허물이 없다.', '象曰：「已日革之」、行有嘉也。'),(293, 49, 3, '九三 征凶。貞厲。革言三就有孚。', '구삼. 나아가면 흉하다. 곧게 지키되 위태롭다. 혁명의 말이 세 번 이루어지면 미더움이 있다.', '象曰：「革言三就」、又何之矣。'),(294, 49, 4, '九四 悔亡。有孚改命吉。', '구사. 뉘우침이 없어진다. 미더움이 있어 명을 고치면 길하다.', '象曰：「改命」之「吉」、信志也。'),(295, 49, 5, '九五 大人虎變，未占有孚。', '구오. 대인이 호랑이처럼 변화하니, 점치지 않아도 미더움이 있다.', '象曰：「大人虎變」、其文炳也。'),(296, 49, 6, '上六 君子豹變，小人革面，征凶，居貞吉。', '상육. 군자는 표범처럼 변하고, 소인은 얼굴을 바꾼다. 나아가면 흉하고, 머물러 곧게 지키면 길하다.', '象曰：「君子豹變」、其文蔚也，「小人革面」、順以從君也。'),(297, 50, 1, '初六 鼎顚趾，利出否。得妾以其子，無咎。', '초육은 솥의 발이 뒤집힌다. 나쁜 것을 쏟아내면 이롭다. 첩을 얻어 그 자식으로 말미암으니 허물이 없다.', '象曰：「鼎顚趾」、未悖也，「利出否」、以從貴也。'),(298, 50, 2, '九二 鼎有實，我仇有疾，不我能卽，吉。', '구이는 솥에 실물이 있으나, 나의 짝이 병이 있어 나에게 나아올 수 없으니 길하다.', '象曰：「鼎有實」、愼所之也，「我仇有疾」、終無尤也。'),(299, 50, 3, '九三 鼎耳革，其行塞，雉膏不食，方雨，虧悔，終吉。', '구삼. 솥의 귀가 바뀌어 그 행함이 막히고, 꿩의 기름을 먹지 못하나, 장차 비가 내려 부족함을 뉘우치고 마침내 길하다.', '象曰：「鼎耳革」、失其義也。'),(300, 50, 4, '九四 鼎折足，覆公餗，其形渥，凶。', '구사. 솥의 다리가 부러져 공의 죽을 엎지르니, 그 모습이 젖어 있으니 흉하다.', '象曰：「覆公餗」、信如何也。'),(301, 50, 5, '六五 鼎黃耳金鉉，利貞。', '육오는 솥의 누런 귀에 쇠 고리이니, 곧게 지키면 이롭다.', '象曰：「鼎黃耳」、中以爲實也。'),(302, 50, 6, '上九 鼎玉鉉，大吉，無不利。', '상구는 솥의 고리가 옥으로 되어 있으니, 크게 길하고 이롭지 않음이 없다.', '象曰：「玉鉉」在「上」、剛柔節也。'),(303, 51, 1, '初九 「震來虩虩」，後「笑言啞啞」，吉。', '초구. 진동이 오니 두려워 떨고, 뒤에 웃으며 말하기를 화락하니, 길하다.', '象曰：「震來虩虩」、恐致福也，「笑言啞啞」、「後」有則也。'),(304, 51, 2, '六二 震來厲，億喪貝，躋于九陵，勿逐，七日得。', '육이는 진(震)이 오니 위태롭다. 헤아려 보니 재물을 잃을 것이니, 구릉(九陵)에 올라가되, 쫓지 말라. 칠 일이면 얻는다.', '象曰：「震來厲」、乘剛也。'),(305, 51, 3, '六三 震蘇蘇，震行無眚。', '육삼은 우레에 정신을 못 차리나, 우레로 인해 행하면 재앙이 없다.', '象曰：「震蘇蘇」、位不當也。'),(306, 51, 4, '九四 震遂泥。', '구사는 진동하나 마침내 진흙에 빠진다.', '象曰：「震遂泥」、未光也。'),(307, 51, 5, '六五 震往來厲，億無喪有事。', '육오는 진(震)이 오고 가니 위태롭다. 억도하여 가진 일을 잃지 않는다.', '象曰：「震往來厲」、危行也，其事在中、大「無喪」也。'),(308, 51, 6, '上六 震索索，視矍矍，征凶。震不于其躬、于其隣、無咎。婚媾有言。', '상육. 진동에 소색하고, 보기에 곽곽하여, 나아가면 흉하다. 진동이 그 몸에 있지 않고 그 이웃에 있으면 허물이 없다. 혼구에 말이 있다.', '象曰：「震索索」、中未得也，雖「凶」「無咎」、畏隣戒也。'),(309, 52, 1, '初六 艮其趾，無咎。利永貞。', '초육은 그 발가락을 그치게 하니, 허물이 없다. 영원히 곧게 지키면 이롭다.', '象曰：「艮其趾」、未失正也。'),(310, 52, 2, '六二 艮其腓，不拯其隨，其心不快。', '육이는 그 종아리를 그치게 하나, 그 따름을 구제하지 못하니, 그 마음이 유쾌하지 않다.', '象曰：「不拯其隨」、未退聽也。'),(311, 52, 3, '九三 艮其限，列其夤，厲薰心。', '구삼은 그 한계를 그치니, 그 등뼈를 갈라놓아 위태로움이 마음을 그을린다.', '象曰：「艮其限」、危「薰心」也。'),(312, 52, 4, '六四 艮其身，無咎。', '육사는 그 몸을 그치게 하니, 허물이 없다.', '象曰：「艮其身」、止諸躬也。'),(313, 52, 5, '六五 艮其輔，言有序，悔亡。', '육오는 그 턱을 그치게 하니, 말에 차례가 있어 뉘우침이 없어진다.', '象曰：「艮其輔」、以中正也。'),(314, 52, 6, '上九 敦艮，吉。', '상구, 돈독하게 그침이니 길하다.', '象曰：「敦艮」之「吉」、以厚終也。'),(315, 53, 1, '初六 鴻漸于干。小子厲有言，無咎。', '초육은 기러기가 물가로 나아간다. 어린아이는 위태로워하며 말이 있으나, 허물이 없다.', '象曰：「小子」之「厲」、義「無咎」也。'),(316, 53, 2, '六二 鴻漸于磐，飮食衎衎，吉。', '육이는 기러기가 반석으로 나아가니, 마시고 먹음이 화락하여 길하다.', '象曰：「飮食衎衎」、不素飽也。'),(317, 53, 3, '九三 鴻漸于陸。夫征不復，婦孕不育，凶。利禦寇。', '구삼. 기러기가 육지로 나아간다. 지아비가 나아가 돌아오지 않고, 지어미가 임신하여도 기르지 못하니, 흉하다. 도적을 막으면 이롭다.', '象曰：「夫征不復」、離群醜也，「婦孕不育」、失其道也，「利用禦寇」、順相保也。'),(318, 53, 4, '六四 鴻漸于木，或得其桷，無咎。', '육사는 기러기가 나무로 나아가니, 혹 그 평평한 가지를 얻으면 허물이 없다.', '象曰：「或得其桷」、順以巽也。'),(319, 53, 5, '九五 鴻漸于陵，婦三歲不孕，終莫之勝，吉。', '구오. 기러기가 언덕으로 나아가니, 부인이 삼 년 동안 잉태하지 못하나, 마침내 이를 이기는 것이 없으니, 길하다.', '象曰：「終莫之勝吉」、得所願也。'),(320, 53, 6, '上九 鴻漸于逵，其羽可用爲儀，吉。', '상구, 기러기가 큰길로 나아가니, 그 깃털을 의장으로 삼을 수 있으니 길하다.', '象曰：「其羽可用爲儀吉」、不可亂也。'),(321, 54, 1, '初九 歸妹以娣。跛能履，征吉。', '초구는 귀매할 때 첩으로 간다. 절름발이가 걸을 수 있으니, 나아가면 길하다.', '象曰：「歸妹以娣」、以恒也，「跛能履」、「吉」相承也。'),(322, 54, 2, '九二 眇能視，利幽人之貞。', '구이는 애꾸눈이지만 볼 수 있으니, 그윽한 사람이 곧게 지키면 이롭다.', '象曰：「利幽人之貞」、未變常也。'),(323, 54, 3, '六三 歸妹以須，反歸以娣。', '육삼은 귀매하되 기다림으로써 하니, 돌이켜 귀하되 첩으로써 한다.', '象曰：「歸妹以須」、未當也。'),(324, 54, 4, '九四 歸妹愆期，遲歸有時。', '구사. 귀매가 기약을 어기니, 늦게 돌아감에 때가 있다.', '象曰：「愆期」之志、有待而行也。'),(325, 54, 5, '六五 帝乙歸妹，其君之袂不如其娣之袂良。月幾望、吉。', '육오. 제을이 누이를 시집보낼 때, 그 임금의 소매가 그 동생의 소매만큼 좋지 않았다. 달이 거의 보름에 이르니 길하다.', '象曰：「帝乙歸妹」、「不如其娣之袂良」也。其位在中，以貴行也。'),(326, 54, 6, '上六 女承筐，無實，士刲羊，無血，無攸利。', '상육. 여자가 광주리를 받들었으나 실속이 없고, 선비가 양을 잡았으나 피가 없으니, 이로울 바가 없다.', '象曰：「上六」「無實」、「承」虛「筐」也。'),(327, 55, 1, '初九 遇其配主，雖旬無咎，往有尙。', '초구는 그 짝 주인을 만나니, 비록 균등하나 허물이 없고, 나아가면 숭상함이 있다.', '象曰：「雖旬無咎」、過旬災也。'),(328, 55, 2, '六二 豊其蔀，日中見斗。往得疑疾，有孚，發若吉。', '육이는 그 가림막을 크게 하니, 한낮에 북두성을 본다. 나아가면 의심과 미움을 얻으나, 미더움이 있어 발하면 길하다.', '象曰：「有孚發若」、信以發志也。'),(329, 55, 3, '九三 豊其沛，日中見沬，折其右肱，無咎。', '구삼. 그 패(沛)를 풍성하게 하니, 한낮에 말(沬)을 보며, 그 오른팔을 꺾으나, 허물이 없다.', '象曰：「豊其沛」、不可大事也，「折其右肱」、終不可用也。'),(330, 55, 4, '九四 豊其蔀，日中見斗，遇其夷主，吉。', '구사는 그 가림막을 크게 하니, 한낮에 북두성을 보며, 그 등이 되는 주인을 만나면 길하다.', '象曰：「豊其蔀」、位不當也。「日中見斗」、幽不明也，「遇其夷主」、「吉」行也。'),(331, 55, 5, '六五 來章，有慶譽，吉。', '육오. 장미한 이를 오게 하면 경사와 명예가 있어 길하다.', '象曰：「六五」之「吉」、有慶也。'),(332, 55, 6, '上六 豊其屋，蔀其家，闚其戶，閴其無人，三歲不覿，凶。', '상육. 그 집을 크게 하고, 그 집을 가리며, 그 문을 엿보니 고요하여 사람이 없다. 삼 년이 되도록 만나지 못하니 흉하다.', '象曰：「豊其屋」、天際翔也。「闚其戶、閴其無人」、自藏也。'),(333, 56, 1, '初六 旅瑣瑣斯，其所取災。', '초육은 나그네로서 쇄쇄하니, 그로써 재앙을 취한다.', '象曰：「旅瑣瑣」、志窮「災」也。'),(334, 56, 2, '六二 旅卽次，懷其資，得童僕貞。', '육이는 나그네가 여관에 이르러 그 재물을 품고 동복(童僕)의 곧음을 얻는다.', '象曰：「得童僕貞」，終無尤也。'),(335, 56, 3, '九三 旅焚其次，喪其童僕貞，厲。', '구삼. 나그네가 그 거처를 불태우고, 그 어린 종을 잃으니, 곧게 지켜도 위태롭다.', '象曰：「旅焚其次」，亦以傷矣。以旅與下，其義「喪」也。'),(336, 56, 4, '九四 旅于處，得其資斧，我心不快。', '구사는 나그네가 머무를 곳에 있어 그 재물과 도끼를 얻었으나, 내 마음이 유쾌하지 않다.', '象曰：「旅于處」、未得位也。「得其資斧」、「心」未「快」也。'),(337, 56, 5, '六五 射雉一矢亡，終以譽命。', '육오. 꿩을 쏘아 한 화살을 잃으니, 마침내 명예와 복록으로써 이른다.', '象曰：「終以譽命」、上逮也。'),(338, 56, 6, '上九 鳥焚其巢，旅人先笑後號咷。喪牛于易，凶。', '상구는 새가 그 둥지를 불사르니, 나그네가 먼저 웃다가 뒤에 울부짖는다. 소를 쉽게 여겨 잃으니 흉하다.', '象曰：以「旅」在「上」、其義「焚」也，「喪牛于易」、終莫之聞也。'),(339, 57, 1, '初六 進退。利武人之貞。', '초육. 나아가고 물러남. 무인의 곧음이 이롭다.', '象曰：「進退」、志疑也，「利武人之貞」、志治也。'),(340, 57, 2, '九二 巽在牀下，用史巫、紛若吉、無咎。', '구이는 손이 평상 아래에 있으니, 사(史)와 무(巫)를 쓰되 분분하면 길하고 허물이 없다.', '象曰：「紛若」之「吉」、得中也。'),(341, 57, 3, '九三 頻巽，吝。', '구삼. 자주 손하니, 부끄러움이 있다.', '象曰：「頻巽」之「吝」、志窮也。'),(342, 57, 4, '六四 悔亡，田獲三品。', '육사는 뉘우침이 없어지고, 사냥하여 세 가지 품등을 얻는다.', '象曰：「田獲三品」、有功也。'),(343, 57, 5, '九五 貞吉，悔亡，無不利，無初有終。先庚三日，後庚三日，吉。', '구오는 곧게 지키면 길하고, 뉘우침이 사라지며, 이롭지 않음이 없다. 처음은 없으나 마침이 있다. 경일보다 사흘 앞서고 경일보다 사흘 뒤하면 길하다.', '象曰：「九五」之「吉」、位正中也。'),(344, 57, 6, '上九 巽在牀下，喪其資斧，貞凶。', '상구, 손이 평상 아래에 있으니, 그 자부를 잃는다. 곧게 지켜도 흉하다.', '象曰：「巽在牀下」、「上」窮也，「喪其資斧」、正乎「凶」也。'),(345, 58, 1, '初九 和兌，吉。', '초구는 화합하여 기뻐하니, 길하다.', '象曰：「和兌」之「吉」、行未疑也。'),(346, 58, 2, '九二 孚兌，吉，悔亡。', '구이. 미더움으로 기뻐하니, 길하고 뉘우침이 사라진다.', '象曰：「孚兌」之「吉」、信志也。'),(347, 58, 3, '六三 來兌，凶。', '육삼. 와태하니 흉하다.', '象曰：「來兌」之「凶」、位不當也。'),(348, 58, 4, '九四 商兌未寧，介疾有喜。', '구사. 기쁨을 헤아리되 아직 편안하지 못하나, 굳게 지키고 사악함을 멀리하면 기쁨이 있다.', '象曰：「九四」之「喜」、有慶也。'),(349, 58, 5, '九五 孚于剝，有厲。', '구오, 벗기는 것을 믿으면 위태로움이 있다.', '象曰：「孚于剝」、位正當也。'),(350, 58, 6, '上六 引兌。', '상육, 끌어당겨 기뻐한다.', '象曰：「上六、引兌」、未光也。'),(351, 59, 1, '初六 用拯馬壯，吉。', '초육은 말이 건장함을 써서 구제하니, 길하다.', '象曰：「初六」之「吉」、順也。'),(352, 59, 2, '九二 渙奔其机，悔亡。', '구이는 흩어짐에 그 기(机)로 달려가니, 뉘우침이 없어진다.', '象曰：「渙奔其机」、得願也。'),(353, 59, 3, '六三 渙其躬，無悔。', '육삼은 그 몸을 흩으니, 뉘우침이 없다.', '象曰：「渙其躬」、志在外也。'),(354, 59, 4, '六四 渙其群，元吉。渙有丘，匪夷所思。', '육사는 그 무리를 흩어 으뜸으로 길하다. 흩어짐에 언덕이 있으니, 평상의 생각이 미치는 바가 아니다.', '象曰：「渙其群元吉」、光大也。'),(355, 59, 5, '九五 渙汗其大號，渙王居，無咎。', '구오. 흩어짐에 땀처럼 그 큰 호령을 내리고, 흩어짐에 왕의 거처를 두면 허물이 없다.', '象曰：「王居無咎」、正位也。'),(356, 59, 6, '上九 渙其血，去逖出，無咎。', '상구. 그 피를 흩어지게 하고, 멀리 떠나 나아가면 허물이 없다.', '象曰：「渙其血」、遠害也。'),(357, 60, 1, '初九 不出戶庭，無咎。', '초구는 문과 뜰을 나가지 않으니, 허물이 없다.', '象曰：「不出戶庭」、知通塞也。'),(358, 60, 2, '九二 不出門庭，凶。', '구이는 문정을 나가지 않으니, 흉하다.', '象曰：「不出門庭凶」、失時極也。'),(359, 60, 3, '六三 不節若，則嗟若，無咎。', '육삼. 절제하지 못하면 탄식하게 되나, 허물은 없다.', '象曰：「不節」之「嗟」、又誰「咎」也。'),(360, 60, 4, '六四 安節。亨。', '육사. 절도를 편안히 하면 형통하다.', '象曰：「安節」之「亨」、承上道也。'),(361, 60, 5, '九五 甘節，吉，往有尙。', '구오. 달게 절제하니 길하고, 나아가면 숭상함이 있다.', '象曰：「甘節」之「吉」、居位中也。'),(362, 60, 6, '上六 苦節，貞凶。悔亡。', '상육은 괴로운 절제이니, 곧게 지키면 흉하다. 뉘우침이 없어진다.', '象曰：「苦節貞凶」、其道窮也。'),(363, 61, 1, '初九 虞吉，有他不燕。', '초구는 헤아려서 길하니, 다른 것이 있으면 편안하지 못하다.', '象曰：「初九、虞吉」、志未變也。'),(364, 61, 2, '九二 鳴鶴在陰，其子和之。我有好爵，吾與爾靡之。', '구이. 학이 그늘에서 울면 그 새끼가 화답한다. 내게 좋은 술잔이 있으니 나는 너와 더불어 그것을 함께 한다.', '象曰：「其子和之」、中心願也。'),(365, 61, 3, '六三 得敵，或鼓或罷，或泣或歌。', '육삼은 적을 얻으니, 혹 북을 치기도 하고 혹 그만두기도 하며, 혹 울기도 하고 혹 노래하기도 한다.', '象曰：「或鼓或罷」、位不當也。'),(366, 61, 4, '六四 月幾望，馬匹亡，無咎。', '육사. 달이 거의 보름이 되고, 짝 말이 없어지니, 허물이 없다.', '象曰：「馬匹亡」、絕類上也。'),(367, 61, 5, '九五 有孚攣如，無咎。', '구오. 미더움이 있어 얽매인 듯하니, 허물이 없다.', '象曰：「有孚攣如」、位正當也。'),(368, 61, 6, '上九 翰音登于天，貞凶。', '상구, 날개 소리가 하늘에 오르니, 곧게 지키면 흉하다.', '象曰：「翰音登于天」、何可長也。'),(369, 62, 1, '初六 飛鳥以凶。', '초육. 나는 새가 이로써 흉하다.', '象曰：「飛鳥以凶」、不可如何也。'),(370, 62, 2, '六二 過其祖，遇其妣。不及其君，遇其臣。無咎。', '육이는 그 조상을 지나쳐서 그 할머니를 만난다. 그 임금에게는 미치지 못하고 그 신하를 만난다. 허물이 없다.', '象曰：「不及其君」、臣不可過也。'),(371, 62, 3, '九三 弗過、防之，從或戕之，凶。', '구삼. 지나치지 않으면 막아야 하니, 따르면 혹 해치게 되어 흉하다.', '象曰：「從或戕之」、「凶」如何也？'),(372, 62, 4, '九四 無咎。弗過、遇之，往厲必戒。勿用永貞。', '구사. 허물이 없다. 지나치지 않고 마주하니, 나아가면 위태로우므로 반드시 경계해야 한다. 영원히 곧게 지킴을 쓰지 말라.', '象曰：「弗過遇之」、位不當也。「往厲必戒」、終不可長也。'),(373, 62, 5, '六五 密雲不雨，自我西郊。公弋取彼在穴。', '육오. 빽빽한 구름이나 비가 내리지 않으니, 우리 서쪽 교외로부터이다. 공이 활을 쏘아 저 구멍에 있는 것을 잡는다.', '象曰：「密雲不雨」、已上也。'),(374, 62, 6, '上六 弗遇、過之，飛鳥離之，凶，是謂災眚。', '상육. 만나지 못하고 지나쳐 버린다. 나는 새가 이를 떠난다. 흉하니, 이를 일러 재앙과 허물이라 한다.', '象曰：「弗遇過之」、已亢也。'),(375, 63, 1, '初九 曳其輪，濡其尾，無咎。', '초구는 그 바퀴를 끌고, 그 꼬리를 적시니, 허물이 없다.', '象曰：「曳其輪」、義「無咎」也。'),(376, 63, 2, '六二 婦喪其茀，勿逐，七日得。', '육이는 부인이 그 너울을 잃었으니, 쫓지 말라. 칠 일이면 얻으리라.', '象曰：「七日得」、以中道也。'),(377, 63, 3, '九三 高宗伐鬼方，三年克之，小人勿用。', '구삼은 고종이 귀방을 치되 삼 년 만에 이겼으니, 소인은 쓰지 말라.', '象曰：「三年克之」、憊也。'),(378, 63, 4, '六四 濡有衣袽，終日戒。', '육사. 젖음이 있어 옷을 찢어 막으니, 종일토록 경계한다.', '象曰：「終日戒」、有所疑也。'),(379, 63, 5, '九五 東隣殺牛，不如西隣之禴祭實受其福。', '구오: 동쪽 이웃이 소를 잡아 제사 지내는 것이, 서쪽 이웃이 약제를 지내는 것만 못하니, 실로 그 복을 받는다.', '象曰：「東隣殺牛」、「不如西隣」之時也。「實受其福」、吉大來也。'),(380, 63, 6, '上六 濡其首，厲。', '상육, 그 머리를 적시니 위태롭다.', '象曰：「濡其首、厲」、何可久也？'),(381, 64, 1, '初六 濡其尾，吝。', '초육은 그 꼬리를 적시니, 부끄럽다.', '象曰：「濡其尾」、亦不知極也。'),(382, 64, 2, '九二 曳其輪，貞吉。', '구이는 그 바퀴를 끌어당긴다. 곧게 지키면 길하다.', '象曰：「九二」「貞吉」、中以行正也。'),(383, 64, 3, '六三 未濟，征凶。利涉大川。', '육삼은 미제(未濟)이니, 나아가면 흉하다. 큰 내를 건너면 이롭다.', '象曰：「未濟征凶」、位不當也。'),(384, 64, 4, '九四 貞吉，悔亡，震用伐鬼方，三年，有賞于大國。', '구사. 곧게 지키면 길하고 뉘우침이 없어진다. 떨쳐 일어나 귀방을 치되 삼 년이 걸려 큰 나라에서 상을 받는다.', '象曰：「貞吉悔亡」、志行也。'),(385, 64, 5, '六五 貞吉，無悔。君子之光，有孚、吉。', '육오. 곧게 지키면 길하고 뉘우침이 없다. 군자의 빛이니, 미더움이 있으면 길하다.', '象曰：「君子之光」、其暉「吉」也。'),(386, 64, 6, '上九 有孚于飮酒，無咎。濡其首，有孚失是。', '상구, 미더움이 있어 술을 마시니 허물이 없다. 그 머리를 적시면 미더움이 있어도 이를 잃는다.', '象曰：「飮酒濡首」、亦不知節也。') ON CONFLICT (id) DO NOTHING;